def parse_query_string(query_string):
    """
    Parses a query string and returns a dictionary of key-value pairs.
    If a key appears more than once, the values are stored in a list.
    If there are no values for a key, it is set to None.

    :param query_string: A string representing the query string from a URL.
    :return: A dictionary with keys mapping to their corresponding values.
    """
    if not query_string:
        return {}

    pairs = query_string.split('&')
    result = {}

    for pair in pairs:
        key_value = pair.split('=')
        key = key_value[0]

        if len(key_value) == 1:
            value = None
        else:
            value = key_value[1]

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result

def factorial_recursive(n: int) -> int:
    """
    Calculate the factorial of a given non-negative integer using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the given integer.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial_recursive(n - 1)

def circular_binary_search(numbers, target):
    """
    Perform a binary search on a circularly sorted list to find the index of the target.

    :param numbers: List[int] - A circularly sorted list of integers.
    :param target: int - The target integer to search for.
    :return: int - The index of the target integer if found, otherwise -1.
    """
    n = len(numbers)
    left, right = 0, n - 1

    while left <= right:
        mid = (left + right) // 2

        if numbers[mid] == target:
            return mid

        if numbers[left] <= numbers[mid]:
            if numbers[left] <= target < numbers[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if numbers[mid] < target <= numbers[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def levenshtein_distance(s1, s2):
    """
    Computes the Levenshtein distance between two strings using dynamic programming.

    :param s1: The first string (source).
    :param s2: The second string (target).
    :return: The Levenshtein distance between s1 and s2.
    """
    len_s1, len_s2 = len(s1), len(s2)
    dp = [[0] * (len_s2 + 1) for _ in range(len_s1 + 1)]

    for i in range(len_s1 + 1):
        dp[i][0] = i
    for j in range(len_s2 + 1):
        dp[0][j] = j

    for i in range(1, len_s1 + 1):
        for j in range(1, len_s2 + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(
                    dp[i - 1][j] + 1,
                    dp[i][j - 1] + 1,
                    dp[i - 1][j - 1] + 1
                )

    return dp[len_s1][len_s2]

def convert_snake_case_to_camel_case(input_data):
    """
    Convert a string from snake_case to camelCase or a nested list of strings from snake_case to camelCase.

    :param input_data: A string in snake_case or a nested list of strings in snake_case.
    :return: The equivalent string in camelCase or a nested list of strings in camelCase.
    """
    def convert_single_string(snake_str):
        components = snake_str.split('_')
        return components[0] + ''.join(x.capitalize() for x in components[1:])

    def recursive_convert(data):
        if isinstance(data, str):
            return convert_single_string(data)
        elif isinstance(data, list):
            return [recursive_convert(item) for item in data]
        else:
            raise ValueError("Input must be a string or a list of strings")

    return recursive_convert(input_data)

def convert_to_json(data):
    """
    Serializes a Python dictionary into a JSON-formatted string.

    Args:
    data (dict): The dictionary to be serialized.

    Returns:
    str: A JSON-formatted string representing the input dictionary.

    Raises:
    TypeError: If the input dictionary contains non-serializable data types.
    """
    if isinstance(data, dict):
        items = [f'"{str(key)}": {convert_to_json(value)}' for key, value in data.items()]
        return f'{{{", ".join(items)}}}'
    elif isinstance(data, (list, tuple)):
        items = [convert_to_json(item) for item in data]
        return f'[{", ".join(items)}]'
    elif isinstance(data, str):
        return f'"{data}"'
    elif isinstance(data, bool):
        return 'true' if data else 'false'
    elif data is None:
        return 'null'
    elif isinstance(data, (int, float)):
        return str(data)
    else:
        raise TypeError(f"Type {type(data)} is not JSON serializable")

def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def is_balanced_parentheses(s: str) -> bool:
    """
    Determines if the parentheses in the string are balanced.

    :param s: A string containing characters including parentheses.
    :return: True if the parentheses are balanced, False otherwise.
    """
    matching_parentheses = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses:
            if not stack or stack[-1] != matching_parentheses[char]:
                return False
            stack.pop()

    return not stack

