def search_matrix(matrix, target):
    """
    Searches for the target value in a 2D matrix where each row and each column is sorted in ascending order.

    :param matrix: List[List[int]] - The 2D matrix to search.
    :param target: int - The target value to find.
    :return: bool - True if the target is found, False otherwise.
    """
    if not matrix or not matrix[0]:
        return False

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return False

def purgeUnnecessaryParameters(config):
    """
    Removes specified parameters from the configuration dictionary based on blacklists.

    Parameters:
    - config (dict): The configuration dictionary to be processed.

    Returns:
    - dict: The modified configuration dictionary with unnecessary parameters removed.
    """
    paramBlacklist = ['unwanted_param1', 'unwanted_param2']  # Example blacklist for top-level
    taskParamBlacklist = ['task_unwanted_param1', 'task_unwanted_param2']  # Example blacklist for tasks

    # Remove top-level parameters
    for param in paramBlacklist:
        if param in config:
            del config[param]

    # Remove parameters from tasks
    for i in range(1, 100):
        task_name = f'Task{i}'
        if task_name in config:
            task = config[task_name]
            for param in taskParamBlacklist:
                if param in task:
                    del task[param]

            # Remove the task if it has no remaining parameters
            if not task:
                del config[task_name]

    return config

def event_frequency(event_string):
    """
    Returns a dictionary summarizing the frequency of each unique event in the given string.

    Parameters:
    event_string (str): A string of events separated by commas.

    Returns:
    dict: A dictionary with events as keys and their frequencies as values.
    """
    if not event_string:
        return {}

