def get_value(data, key):
    """
    Retrieves the value associated with the nested key from a dictionary or object.

    Args:
    - data: A dictionary or an object with attributes.
    - key: A string representing the path to the desired value, with keys/attributes separated by dots.

    Returns:
    - The value associated with the key if it exists, otherwise an empty string.
    """
    keys = key.split('.')
    for k in keys:
        try:
            if isinstance(data, dict):
                data = data[k]
            elif hasattr(data, k):
                data = getattr(data, k)
            else:
                return ""
        except (KeyError, AttributeError):
            return ""
    return data if data is not None else ""

def most_frequent(word_list):
    """
    Returns the most frequently occurring word in the list.
    In case of a tie, returns the word that appears first in the list.

    :param word_list: List of strings representing the words.
    :return: String representing the most frequently occurring word.
    """
    word_count = {}
    for word in word_list:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    max_count = 0
    most_frequent_word = None

    for word in word_list:
        if word_count[word] > max_count:
            max_count = word_count[word]
            most_frequent_word = word

    return most_frequent_word

def prime_sums(limit):
    """
    Calculate the sum of all prime numbers up to and including the given limit.

    Parameters:
    limit (int): The upper bound up to which prime numbers are summed.

    Returns:
    int: The sum of all prime numbers up to and including the limit.

    Raises:
    ValueError: If the limit is not an integer.
    """
    if not isinstance(limit, int):
        raise ValueError("Limit must be an integer (whole number).")
    if limit < 2:
        return 0

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for num in range(2, int(limit**0.5) + 1):
        if is_prime[num]:
            for multiple in range(num*num, limit + 1, num):
                is_prime[multiple] = False

    return sum(index for index, prime in enumerate(is_prime) if prime)

from functools import lru_cache

def optimize_function(f):
    """
    Returns a new function that is optimized for performance using LRU caching.

    Parameters:
    f (function): A mathematical function that takes a single argument x.

    Returns:
    function: A new function g that computes the same output as f but is optimized.
    """
    @lru_cache(maxsize=None)
