def is_balanced_parentheses(expression: str) -> bool:
    """
    Determines if the brackets in the given expression are balanced.

    :param expression: A string containing alphanumeric characters and the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the brackets are balanced, False otherwise.
    """
    bracket_map = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in expression:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        elif char in bracket_map.values():
            stack.append(char)

    return not stack

