def maxProfit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List[int] - A list of integers representing stock prices on consecutive days.
    :return: int - The maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

