    Strings that cannot be converted to integers are ignored.

    :param numbers: List of strings, each representing a number.
    :return: Sum of integers at even indices.
    """
    total = 0
    for index, num_str in enumerate(numbers):
        if index % 2 == 0:
            try:
                total += int(num_str)
            except ValueError:
                continue
    return total

