def count_leaves(node):
    """
    Counts the number of leaf nodes in a tree using a depth-first search algorithm without recursion.

    :param node: A dictionary representing the root node of the tree, or a string representing a leaf node.
    :return: An integer representing the number of leaf nodes in the tree.
    """
    stack = [node]
    leaf_count = 0

    while stack:
        current = stack.pop()

