def find_largest_prime(n):
    """
    Finds the largest prime number less than or equal to `n`.

    Args:
    n (int): The upper limit to search for the largest prime.

    Returns:
    int: The largest prime number less than or equal to `n`.
         If `n` is less than 2, returns None as there are no prime numbers less than 2.
    """
    if n < 2:
        return None

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while p ** 2 <= n:
        if is_prime[p]:
            for multiple in range(p ** 2, n + 1, p):
                is_prime[multiple] = False
        p += 1

    for largest_prime in range(n, 1, -1):
        if is_prime[largest_prime]:
            return largest_prime
    return 2

def hex2rgb(hex_code):
    """
    Converts a hexadecimal color code into an RGB tuple.

    Parameters:
    hex_code (str): A string representing the hexadecimal color code.

    Returns:
    tuple: A tuple containing the red, green, and blue values as integers in the range [0, 255].

    Raises:
    ValueError: If the input is not a valid hexadecimal color code.
    """
    def normalize_hex(hex_code):
        if hex_code.startswith('#'):
            hex_code = hex_code[1:]

        if len(hex_code) == 3:  # shorthand mode
            hex_code = ''.join([c*2 for c in hex_code])
        elif len(hex_code) != 6:
            raise ValueError("Invalid hexadecimal color code")

        try:
            return int(hex_code, 16)
        except ValueError:
            raise ValueError("Invalid hexadecimal color code")

    if not isinstance(hex_code, str):
        raise ValueError("Input must be a string")

    # Normalize and convert to integer
    rgb_int = normalize_hex(hex_code)

    # Split into RGB components
    red = (rgb_int >> 16) & 0xFF
    green = (rgb_int >> 8) & 0xFF
    blue = rgb_int & 0xFF

    return (red, green, blue)

def emotion_classifier(emotion_score):
    """
    Classifies the emotion based on the given emotion score.

    Parameters:
    emotion_score (float or list): A floating-point number or a nested list of floating-point numbers representing emotion intensity.

    Returns:
    str or list: A string representing the emotion category or a nested list of emotion categories.
    """
    def classify(score):
        """
        Classifies a single emotion score.

        Parameters:
        score (float or None): A floating-point number representing emotion intensity or None.

        Returns:
        str or None: A string representing the emotion category or None.
        """
        if score is None:
            return None
        elif score < -0.5:
            return 'Sad'
        elif -0.5 <= score <= 0.5:
            return 'Neutral'
        elif score > 0.5:
            return 'Happy'

    if isinstance(emotion_score, list):
        return [emotion_classifier(sub_score) if isinstance(sub_score, list) else classify(sub_score) for sub_score in emotion_score]
    else:
        return classify(emotion_score)

def find_rotation_point(arr):
    """
    Returns the index of the smallest element in a rotated sorted array that may contain duplicates.

    :param arr: List[int] - A list of integers representing the rotated sorted array.
    :return: int - The index of the smallest element in the array.
    """
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        elif arr[mid] < arr[high]:
            high = mid
        else:
            high -= 1
    return low

def check_frequency_distribution(iterable, distribution):
    """
    Determines if the frequency distribution of elements in the iterable matches the given distribution exactly.

    :param iterable: An iterable (e.g., list or string) containing elements to be counted.
    :param distribution: A dictionary with elements as keys and their expected frequencies as values.
    :return: True if the frequency distribution matches exactly, False otherwise.
    """
    from collections import Counter

    iterable_counter = Counter(iterable)

    for element, frequency in distribution.items():
        if iterable_counter[element] != frequency:
            return False

    for element in iterable_counter:
        if element not in distribution:
            return False

    return True

def compare_sequences(seq1, seq2):
    """
    Compares two nested lists to determine if their flattened versions are identical.

    :param seq1: First nested list.
    :param seq2: Second nested list.
    :return: True if the flattened versions of seq1 and seq2 are identical, False otherwise.
    """
    def flatten(sequence):
        """
        Flattens a nested list into a single list of integers.

        :param sequence: Nested list to be flattened.
        :return: Generator yielding elements of the flattened list.
        """
        for item in sequence:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    return list(flatten(seq1)) == list(flatten(seq2))

def prime_factorization(n):
    """
    Returns a dictionary with prime factors of n as keys and their respective exponents as values.

    :param n: Integer to factorize
    :return: Dictionary of prime factors and their exponents
    """
    def prime_factors(n):
        i = 2
        factors = {}
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors[i] = factors.get(i, 0) + 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    return prime_factors(n)

