def calculate_average(nested_list):
    """
    Computes the average of all numeric values in a nested list.

    Parameters:
    nested_list (list): A nested list of elements which can be integers, floats, or other lists.

    Returns:
    float: The average of all numeric values in the nested list.
    str: The string "The list is empty or contains non-numeric values." if the list is empty or contains non-numeric values.
    """
    def flatten(lst):
        """Helper function to flatten a nested list."""
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flat_list = list(flatten(nested_list))

    if not flat_list:
        return "The list is empty or contains non-numeric values."

    total_sum = 0
    count = 0

    for num in flat_list:
        if isinstance(num, (int, float)):
            total_sum += num
            count += 1
        else:
            return "The list is empty or contains non-numeric values."

    if count > 0:
        return total_sum / count
    else:
        return "The list is empty or contains non-numeric values."

