def validateCustomEncoding(data):
    """
    Validates if the given list of integers represents a valid custom encoding.

    Parameters:
    data (List[int]): A list of integers where each integer represents a byte of data.

    Returns:
    bool: True if the data set is valid according to the custom encoding rules, False otherwise.
    """
    i = 0
    n = len(data)

    while i < n:
        mask = 1 << 7
        count = 0
        while mask & data[i] != 0:
            count += 1
            mask >>= 1

        if count == 0:
            if (data[i] & 1 << 7) != 0:
                return False
            i += 1
            continue

        if count == 1 or count > 4:
            return False

        if i + count > n:
            return False

        for j in range(i + 1, i + count):
            if (data[j] & 0xC0) != 0x80:
                return False

        i += count

    return True

def convert_to_string(data, encoding="UTF-8"):
    """
    Converts all non-string elements in the given data structure to strings while preserving the original structure.

    Parameters:
    - data: The data structure to be processed.
    - encoding: A string representing the encoding format (not used in conversion).

    Returns:
    - A new data structure with all non-string elements converted to strings.
    """
    def recursive_convert(element):
        if isinstance(element, str):
            return element
        elif isinstance(element, (int, float, bool)):
            return str(element)
        elif isinstance(element, dict):
            return {recursive_convert(k): recursive_convert(v) for k, v in element.items()}
        elif isinstance(element, (list, tuple, set)):
            return type(element)(recursive_convert(item) for item in element)
        else:
            return str(element)

    return recursive_convert(data)

def sign_count(arr):
    """
    Returns a dictionary with unique non-negative integers from the list as keys.
    Each key maps to another dictionary with 'count' and 'sum' as keys.
    'count' represents the number of occurrences of the integer in the list.
    'sum' represents the total sum of all occurrences of the integer in the list.

    :param arr: List of integers
    :return: Dictionary with non-negative integers as keys and nested dictionaries as values
    """
    result = {}
    for num in arr:
        if num >= 0:
            if num in result:
                result[num]['count'] += 1
                result[num]['sum'] += num
            else:
                result[num] = {'count': 1, 'sum': num}
    return result

def get_separator_order(dict_levels):
    """
    Returns a list of keys from the dictionary sorted by level and then by separators
    according to the priority: ',', ' ', '+', '-'.

    :param dict_levels: Dictionary with keys in the format "<level>_<separators>"
    :return: List of sorted keys
    """
    separator_order = [',', ' ', '+', '-']

    def sort_key(key):
        level, separators = key.split('_', 1)
        priority = [separator_order.index(s) for s in separators]
        return (int(level), priority)

    return sorted(dict_levels.keys(), key=sort_key)

def compute_factorial(n):
    """
    Computes the factorial of a given non-negative integer using recursion.
    If the input is negative, returns -1.

    Parameters:
    n (int): The integer for which the factorial is to be computed.

    Returns:
    int: The factorial of n if n is non-negative, otherwise -1.
    """
    if n < 0:
        return -1
    elif n == 0 or n == 1:
        return 1
    else:
        return n * compute_factorial(n - 1)

def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries of chemical elements, summing atomic weights for common elements
    and selecting the earlier discovery year.

    :param dict1: First dictionary of elements with (atomic_weight, discovery_year) tuples.
    :param dict2: Second dictionary of elements with (atomic_weight, discovery_year) tuples.
    :return: Merged dictionary with updated properties.
    """
    merged_dict = {}

    for element in dict1:
        if element in dict2:
            atomic_weight_sum = dict1[element][0] + dict2[element][0]
            discovery_year = min(dict1[element][1], dict2[element][1])
            merged_dict[element] = (atomic_weight_sum, discovery_year)
        else:
            merged_dict[element] = dict1[element]

    for element in dict2:
        if element not in dict1:
            merged_dict[element] = dict2[element]

    return merged_dict

