    """
    Determines if there is exactly one king on the board and no other pieces.

    :param board: A 2D list representing the chessboard.
    :return: True if there is exactly one king, False otherwise.
    """
    king_count = 0

    for row in board:
        for cell in row:
            if cell != 0:
                king_count += 1
                if king_count > 1:
                    return False

    return king_count == 1

