def is_balanced_parentheses(s: str) -> bool:
    """
    Determines if the input string s containing only the characters '(', ')', '{', '}', '[' and ']'
    is balanced. A string is considered balanced if all open brackets are closed in the correct order.

    :param s: The input string to check for balanced parentheses.
    :return: True if the string is balanced, False otherwise.
    """
    bracket_map = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    tails = []

    for num in nums:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

