    """
    Finds the element in the sorted list `arr` that is closest to the target integer `x`.
    If there are multiple elements equally close to `x`, returns the one with the smallest index.

    :param arr: List[int] - A sorted list of integers.
    :param x: int - The target integer.
    :return: int - The element in `arr` closest to `x`.
    """
    if not arr:
        return None  # Return None if the list is empty

    left, right = 0, len(arr) - 1

    while left < right - 1:
        mid = (left + right) // 2
        if arr[mid] == x:
            return arr[mid]
        elif arr[mid] < x:
            left = mid
        else:
            right = mid

    # After the loop, left and right are neighbors
    # Check which one is closer to x
    if abs(arr[left] - x) <= abs(arr[right] - x):
        return arr[left]
    else:
        return arr[right]

def generate_summary(sentences):
