def any_odd(iterable):
    """
    Determines if there is at least one odd number in the iterable.

    Parameters:
    iterable (iterable): An iterable of integers.

    Returns:
    bool: True if there is at least one odd number, False otherwise.
    """
    it = iter(iterable)
    while True:
        try:
            num = next(it)
            if num - ((num >> 1) << 1):
                return True
        except StopIteration:
            return False

def check_balanced_parentheses(s: str) -> bool:
    """
    Determines if the input string has balanced parentheses, brackets, and braces.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is balanced, otherwise False.
    """
    mapping = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if stack and stack[-1] == mapping[char]:
                stack.pop()
            else:
                return False

    return not stack

def categorize_indices_by_id(numbers_list):
    """
