    Returns:
    list of list of int: A list of lists, where each sublist contains the indices
                         of numbers_list that belong to the same category.
    """
    id_to_indices = {}

    for index, number in enumerate(numbers_list):
        if number not in id_to_indices:
            id_to_indices[number] = []
        id_to_indices[number].append(index)

    return list(id_to_indices.values())

def unique_integers(input_list):
    """
    Returns a list of unique integers from the input list, preserving the order of their first appearance.

    :param input_list: List of integers
    :return: List of unique integers
    """
    seen = {}
    unique_list = []

    for number in input_list:
        if number not in seen:
            seen[number] = True
            unique_list.append(number)

    return unique_list

def find_min_data_source(data_vol_delivered_allsources, target_names):
    """
    Finds the data source from the target_names list that has delivered the least volume of data.

    Parameters:
    data_vol_delivered_allsources (dict): A dictionary with data source names as keys and their respective data volumes as values.
    target_names (list): A list of data source names to consider.

    Returns:
    tuple: A tuple containing the name of the data source with the least volume and the volume itself.
    """
    def convert_volume(value):
        if isinstance(value, str):
            value = value.replace(',', '')
        return float(value)

    min_volume = float('inf')
    min_source = None

    for source in target_names:
        if source in data_vol_delivered_allsources:
            vol = convert_volume(data_vol_delivered_allsources[source])
            if vol < min_volume:
                min_volume = vol
                min_source = source

    return (min_source, min_volume)

def calculate_sum_product_average(numbers):
    """
    Computes the sum, product, and average of a list of integers.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    tuple: A tuple containing the sum, product, and average of the integers.
    """
    if not numbers:
        return (0, 0, 0)

    total_sum = sum(numbers)
    total_product = 1
    for number in numbers:
        total_product *= number
    average = total_sum / len(numbers)

    return (total_sum, total_product, average)

def find_odd_occurrence(numbers):
    """
    Finds and returns the first integer that appears an odd number of times in the list.
    If no such integer exists, returns None.

    :param numbers: List of integers
    :return: The first integer with an odd count or None if no such integer exists
    """
    counts = {}
    for number in numbers:
        counts[number] = counts.get(number, 0) + 1

    for number in numbers:
        if counts[number] % 2 != 0:
            return number

    return None

