def compare_dictionaries(dict1, dict2):
    """
    Compares two dictionaries and returns a new dictionary containing the differences.

    Parameters:
    dict1 (dict): The first dictionary.
    dict2 (dict): The second dictionary.

    Returns:
    dict: A dictionary highlighting the differences between dict1 and dict2.
    """
    def compare_values(v1, v2):
        if isinstance(v1, dict) and isinstance(v2, dict):
            return compare_dictionaries(v1, v2)
        elif v1 != v2:
            return (v1, v2)
        else:
            return None

    keys = set(dict1.keys()).union(set(dict2.keys()))
    diff = {}

    for key in keys:
        value1 = dict1.get(key)
        value2 = dict2.get(key)

        if key in dict1 and key not in dict2:
            diff[key] = (value1, None)
        elif key not in dict1 and key in dict2:
            diff[key] = (None, value2)
        else:
            comparison_result = compare_values(value1, value2)
            if comparison_result is not None:
                diff[key] = comparison_result

    return diff

def generate_pagination(current_page, total_pages, max_visible_pages=5):
    """
    Generates a list of page numbers for a pagination scheme.

    Parameters:
    - current_page (int): The current page number.
    - total_pages (int): The total number of pages.
    - max_visible_pages (int): The maximum number of visible pages in the pagination scheme.

    Returns:
    - list: A list of page numbers to be displayed.
    """
    if max_visible_pages < 3:
        raise ValueError("max_visible_pages must be at least 3")

    if current_page < 1:
        current_page = 1
    elif current_page > total_pages:
        current_page = total_pages

    half_max = max_visible_pages // 2
    if current_page <= half_max:
        start = 1
        end = min(total_pages, max_visible_pages)
    elif current_page >= total_pages - half_max + 1:
        start = max(1, total_pages - max_visible_pages + 1)
        end = total_pages
    else:
        start = current_page - half_max
        end = min(current_page + half_max, total_pages)

    return list(range(start, end + 1))

