def find_duplicate_elements(numbers):
    """
    Finds and returns a list of duplicate elements in the input list `numbers`.

    :param numbers: List of integers
    :return: List of integers that appear more than once in `numbers`
    """
    n = len(numbers)
    duplicates = []
    for i in range(n):
        count = 0
        for j in range(n):
            if numbers[i] == numbers[j]:
                count += 1
        if count > 1 and numbers[i] not in duplicates:
            duplicates.append(numbers[i])
    return duplicates

def get_prime_factors(n):
    """
    Returns a list of all distinct prime factors of the given integer n.

    :param n: Integer, the number to factorize
    :return: List of integers, the distinct prime factors of n in ascending order
    """
    i = 2
    factors = set()  # Using set to avoid duplicate prime factors
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.add(i)
    if n > 1:
        factors.add(n)
    return sorted(factors)

