def is_valid(s: str) -> bool:
    """
    Determines if a string of brackets is valid.

    A string is considered valid if all brackets are closed in the correct order.

    :param s: String containing only the characters '(', ')', '{', '}', '[', ']'.
    :return: True if the string is valid, False otherwise.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or mapping[char] != stack.pop():
                return False
        else:
            return False
    return not stack

def find_common_elements(list1, list2):
    """
    Returns a list of elements that are common to both input lists.

    :param list1: List of integers.
    :param list2: List of integers.
    :return: List of integers that are common to both list1 and list2.
    """
    # Create a dictionary to count occurrences
    count_dict = {}

    # Count each element in list1
    for item in list1:
        if item in count_dict:
            count_dict[item] += 1
        else:
            count_dict[item] = 1

    # Find common elements in list2
    common_elements = []
    for item in list2:
        if item in count_dict and count_dict[item] > 0:
            common_elements.append(item)
            count_dict[item] -= 1  # Decrease count to handle duplicates correctly

    return common_elements

