def binary_search(arr, target):
    """
    Perform a binary search on a sorted list to find the index of the target value.

    Parameters:
    arr (list of int): The sorted list to search.
    target (int): The target value to find.

    Returns:
    int: The index of the target value in the list, or -1 if not found.
    """
    def search_recursive(arr, target, low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return search_recursive(arr, target, mid + 1, high)
        else:
            return search_recursive(arr, target, low, mid - 1)

    return search_recursive(arr, target, 0, len(arr) - 1)

