def is_balanced_parentheses(s):
    """
    Determines if the parentheses in the string are balanced.

    :param s: A string containing characters, including parentheses.
    :return: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def extract_first_value(data):
    """
    Recursively extracts the first non-iterable or string element from the given data.

    Parameters:
    data: Can be of any data type.

    Returns:
    The first non-iterable or string element found in the data.
    """
    def is_string_and_not_iterable(data):
        return isinstance(data, str)

    def is_iterable(data):
        try:
            iter(data)
            return True
        except TypeError:
            return False

    def extract_first(data):
        if is_string_and_not_iterable(data):
            return data
        elif is_iterable(data) and not isinstance(data, dict):
            for item in data:
                result = extract_first(item)
                if result is not None:
                    return result
        return data

    return extract_first(data)

def build_tree(edges):
    """
    Constructs an adjacency list representation of a graph from a list of directed edges.

    Parameters:
    edges (list of tuples): A list where each tuple (src, dest) represents a directed edge from node src to node dest.

    Returns:
    dict: An adjacency list representation of the graph.
    """
    tree = {}
    for src, dest in edges:
        if src in tree:
            tree[src].append(dest)
        else:
            tree[src] = [dest]
    return tree

def count_strings(code):
    """
    Counts the total number of strings in the given code snippet, handling nested strings and comments.

    :param code: A string representing the code snippet.
    :return: An integer representing the total number of strings in the code.
    """
    in_single_quote = False
    in_double_quote = False
    in_single_comment = False
    in_multi_comment = False
    string_count = 0
    escape_next = False
    i = 0
    n = len(code)

    while i < n:
        if in_single_comment:
            if code[i] == '\n':
                in_single_comment = False
        elif in_multi_comment:
            if i < n-1 and code[i] == '*' and code[i+1] == '/':
                in_multi_comment = False
                i += 1  # Skip the '/'
        else:
            if escape_next:
                escape_next = False
            elif code[i] == '\\':
                escape_next = True
            elif code[i] == '\'' and not in_double_quote:
                if not in_single_quote:
                    in_single_quote = True
                    string_count += 1
                else:
                    in_single_quote = False
            elif code[i] == '"' and not in_single_quote:
                if not in_double_quote:
                    in_double_quote = True
                    string_count += 1
                else:
                    in_double_quote = False
            elif i < n-1 and code[i] == '/' and code[i+1] == '/':
                in_single_comment = True
                i += 1  # Skip the second '/'
            elif i < n-1 and code[i] == '/' and code[i+1] == '*':
                in_multi_comment = True
                i += 1  # Skip the second '*'
        i += 1

    return string_count

def calculate_factorial(n):
    """
    Calculate the factorial of a given non-negative integer n using recursion.

    Parameters:
    n (int): The non-negative integer for which the factorial is to be calculated.

    Returns:
    int or str: The factorial of n if n is non-negative, otherwise an error message.
    """
    if n < 0:
        return "Input is invalid. Please enter a non-negative integer."
    elif n == 0 or n == 1:
        return 1
    else:
        return n * calculate_factorial(n - 1)

