def unpad(data: bytes, size: int) -> bytes:
    """
    Removes PKCS#7 padding from the supplied byte string.

    Parameters:
    data (bytes): The byte string from which to remove padding.
    size (int): The block size used for padding.

    Returns:
    bytes: The original data without padding, or None if padding is invalid.
    """
    if not isinstance(data, bytes):
        return None

    if size <= 0:
        return None

    if len(data) % size != 0:
        return None

    if not data:
        return data

    padding_length = data[-1]

    if padding_length > size:
        return None

    if padding_length == 0:
        return None

    if data[-padding_length:] != bytes([padding_length]) * padding_length:
        return None

    return data[:-padding_length]

def calculator(operation, a, b):
    """
    Perform a basic arithmetic operation on two numbers.

    Parameters:
    operation (str): The arithmetic operation to perform ('add', 'subtract', 'multiply', 'divide').
    a (int or float): The first operand.
    b (int or float): The second operand.

    Returns:
    int or float or str: The result of the operation or an error message if inputs are invalid.
    """
    try:
        if operation == 'add':
            return a + b
        elif operation == 'subtract':
            return a - b
        elif operation == 'multiply':
            return a * b
        elif operation == 'divide':
            if b == 0:
                raise ValueError("Cannot divide by zero.")
            return a / b
        else:
            raise ValueError("Invalid operation. Supported operations are: add, subtract, multiply, divide.")
    except TypeError:
        return "Invalid input type. Please provide numbers for the operands."
    except ZeroDivisionError:
        return "Cannot divide by zero."
    except ValueError as ve:
        return str(ve)

def find_longest_common_prefix(words):
    """
    Finds the longest common prefix among all strings in the given list.

    :param words: List of strings
    :return: Longest common prefix as a string
    """
    if not words:
        return ""

    prefix = words[0]

    for word in words[1:]:
        while word[:len(prefix)] != prefix and prefix:
            prefix = prefix[:-1]
        if not prefix:
            return ""

    return prefix

def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List of integers representing the annual profit or loss.
    :return: Integer representing the maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        else:
            potential_profit = price - min_price
            if potential_profit > max_profit:
                max_profit = potential_profit

    return max_profit

def find_max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List[int] - A list of stock prices where prices[i] is the price of the stock on day i.
    :return: int - The maximum profit that can be achieved from a single transaction. If no profit is possible, return 0.
    """
    if not prices:
        return 0

    max_profit = 0
    min_price = float('inf')

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

