def is_valid(s: str) -> bool:
    """
    Determines if the input string s containing only '(', ')', '{', '}', '[' and ']' is valid.
    A string is valid if all opening brackets have a corresponding closing bracket of the same type
    and the brackets are closed in the correct order.

    :param s: The input string consisting of brackets.
    :return: True if the string is valid, False otherwise.
    """
    matching_pairs = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs.keys():
            if stack and stack[-1] == matching_pairs[char]:
                stack.pop()
            else:
                return False
        else:
            return False

    return not stack

def generate_identifiers(items):
    """
    Generates unique, two-digit identifiers for a list of items.

    Parameters:
    items (list of str): The list of items to generate identifiers for.

    Returns:
    list of str: A list of unique, two-digit identifiers.

    Raises:
    Exception: If there are more unique items than available identifiers.
    """
    identifier_map = {}
    counter = 0

    for item in items:
        if item not in identifier_map:
            if counter >= 100:
                raise Exception("More items than available unique identifiers.")
            identifier_map[item] = str(counter).zfill(2)
            counter += 1

    return list(identifier_map.values())

def find_longest_increasing_subsequence(nums):
    """
    Finds the length of the longest increasing subsequence in a list of integers.

    :param nums: List of integers.
    :return: Length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def concatenate_excluding_vowels(char_list):
    """
    Concatenates characters from the input list into a single string, excluding vowels.

    Parameters:
    char_list (list of str): A list where each element is a single character string.

    Returns:
    str: A string formed by concatenating all non-vowel characters from the input list.
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    return ''.join(char for char in char_list if char not in vowels)

def determine_product_quality(score):
    """
    Determines the quality of a product based on its inspection score.

    Parameters:
    score (int): The inspection score of the product, an integer between 0 and 100 inclusive.

    Returns:
    str: The quality classification of the product ("Premium", "Standard", "Below Average", "Defective", "Invalid Score", or "Score must be even").
    """
    if not isinstance(score, int) or score < 0 or score > 100:
        return "Invalid Score"
    if score % 2 != 0:
        return "Score must be even"
    if score >= 90:
        return "Premium"
    elif 60 <= score <= 89:
        return "Standard"
    elif 30 <= score <= 59:
        return "Below Average"
    else:
        return "Defective"

from typing import List

def quick_select_largest(numbers: List[int], k: int) -> int:
    """
    Finds the kth largest element in an unsorted list of integers using a method similar to quick sort.

    :param numbers: List of integers.
    :param k: The kth position to find the largest element for (1-based index).
    :return: The kth largest element in the list.
    """
    def partition(low: int, high: int) -> int:
        pivot_index = high
        pivot_value = numbers[pivot_index]
        i = low
        for j in range(low, high):
            if numbers[j] > pivot_value:
                numbers[i], numbers[j] = numbers[j], numbers[i]
                i += 1
        numbers[i], numbers[pivot_index] = numbers[pivot_index], numbers[i]
        return i

    def quick_select(low: int, high: int, k: int) -> int:
        if low == high:
            return numbers[low]

        pivot_index = partition(low, high)

        if k == pivot_index:
            return numbers[k]
        elif k < pivot_index:
            return quick_select(low, pivot_index - 1, k)
        else:
            return quick_select(pivot_index + 1, high, k)

    if not numbers or k <= 0 or k > len(numbers):
        raise ValueError("Invalid input")

    k = k - 1
    return quick_select(0, len(numbers) - 1, k)

def check_prime(n):
    """
    Determines if the given integer n is a prime number.

    Parameters:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_edge_distance(node1, node2, edges):
    """
    Returns the distance of the directed edge from node1 to node2 if it exists,
    or -1 if it does not exist.

    :param node1: str, the starting node
    :param node2: str, the ending node
    :param edges: list of tuples, where each tuple contains two strings (nodes) and an integer (distance)
    :return: int, the distance of the edge or -1 if no such edge exists
    """
    graph = {}

    for u, v, weight in edges:
        if u in graph:
            graph[u][v] = weight
        else:
            graph[u] = {v: weight}

    if node1 in graph and node2 in graph[node1]:
        return graph[node1][node2]
    else:
        return -1

def event2code(event_details):
    """
    Constructs a new dictionary with keys 'e_name', 'e_location', 'e_date', and 'e_code'
    from the input dictionary 'event_details'. If a key is missing in the input dictionary,
    the corresponding value in the output dictionary is set to None.

    :param event_details: Dictionary containing event information with possible keys
                          'event_name', 'event_location', 'event_date', and 'event_code'.
    :return: A new dictionary with keys 'e_name', 'e_location', 'e_date', and 'e_code'.
    """
    new_keys = ['event_name', 'event_location', 'event_date', 'event_code']
    new_key_prefixes = ['e_name', 'e_location', 'e_date', 'e_code']
    new_dict = {}

    for new_key, old_key in zip(new_key_prefixes, new_keys):
        if old_key in event_details:
            new_dict[new_key] = event_details[old_key]
        else:
            new_dict[new_key] = None

    return new_dict

