    :param words: List of strings where each string is a word.
    :return: A list of lists, where each sublist contains words that are anagrams of each other.
    """
    anagrams = {}
    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagrams:
            anagrams[sorted_word].append(word)
        else:
            anagrams[sorted_word] = [word]
    return list(anagrams.values())

def is_valid_parentheses_sequence(s):
    """
    Determines if the given string s represents a valid sequence of nested parentheses.

    :param s: A string consisting of '(' and ')'.
    :return: True if the sequence is valid, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def find_fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    Parameters:
    n (int): A non-negative integer representing the position in the Fibonacci sequence.

    Returns:
    int: The nth Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return find_fibonacci(n-1) + find_fibonacci(n-2)

