def calculateSquareRoot(number):
    """
    Computes the square root of a given number.

    Parameters:
    number: The number to compute the square root of.

    Returns:
    The square root of the number if it is a non-negative number.
    An error message if the input is invalid.
    """
    try:
        if number < 0:
            raise ValueError("Input must be a non-negative number.")
        return number ** 0.5
    except TypeError:
        return "Input must be a number."
    except ValueError as ve:
        return str(ve)

def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers less than or equal to n.

    :param n: An integer representing the upper limit.
    :return: The sum of all prime numbers less than or equal to n.
    """
    if n < 2:
        return 0
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for start in range(2, int(n ** 0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n + 1, start):
                sieve[multiple] = False
    return sum(index for index, is_prime in enumerate(sieve) if is_prime)

def word_frequency(s):
