    Returns a dictionary with the frequency of each word in the input string.

    :param s: A string consisting of lowercase English letters separated by spaces.
    :return: A dictionary with words as keys and their frequencies as values.
    """
    words = s.split()
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency

