def convert_string_to_bool_v2(value):
    """
    Converts an input value to a Boolean value based on specific string matching rules.

    Parameters:
    value: The input value to be converted.

    Returns:
    bool: True if the cleaned string matches "TRUE", "YES", "1", or "ON".
          False if the cleaned string matches "FALSE", "NO", "0", or "OFF".
          The original input value for all other cases.
    """
    if isinstance(value, str):
        cleaned_value = value.replace(" ", "").upper()
        true_values = {"TRUE", "YES", "1", "ON"}
        false_values = {"FALSE", "NO", "0", "OFF"}

        if cleaned_value in true_values:
            return True
        elif cleaned_value in false_values:
