    return True

def simple_calculator(expression):
    """
    Evaluates a simple arithmetic expression given as a string.

    Args:
    expression (str): A string in the format "operand1 operator operand2".

    Returns:
    float or str: The result of the arithmetic operation or an error message.
    """
    operand1, operator, operand2 = expression.split()
    operand1 = float(operand1)
    operand2 = float(operand2)

    if operator == '+':
        return operand1 + operand2
    elif operator == '-':
        return operand1 - operand2
    elif operator == '*':
        return operand1 * operand2
    elif operator == '/':
        if operand2 == 0:
            return "Error: Division by zero"
        return operand1 / operand2
    else:
        return "Error: Unsupported operator"

def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with dot-separated keys.
    Only string values are included in the final dictionary.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A flattened dictionary with only string values.
    :raises TypeError: If the input is not a dictionary.
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    flat_dict = {}
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            flat_dict.update(flatten_dict(v, new_key, sep=sep))
        elif isinstance(v, str):
            flat_dict[new_key] = v
    return flat_dict

def is_valid_sequence(s: str) -> bool:
    """
    Determines if the input string s is a valid sequence of brackets.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is a valid sequence of brackets, otherwise False.
    """
    matching_pairs = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    stack = []

    for char in s:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs.keys():
            if stack and stack[-1] == matching_pairs[char]:
                stack.pop()
            else:
                return False
        else:
            return False

    return not stack

