def apply_escaping(val, escape=False):
    """
    Processes a string by escaping specific characters if the escape flag is True.

    Parameters:
    val (str): The input string to be processed.
    escape (bool): A flag indicating whether to apply escape sequences (default is False).

    Returns:
    str: The processed string with escape sequences applied if escape is True, otherwise the original string.
    """
    if not escape:
        return val

    escape_chars = {
        "'": "\\'",
        '"': '\\"',
        '\\': '\\\\',
        'n': '\n'
    }

    result = []

    for char in val:
        if char in escape_chars:
            result.append(escape_chars[char])
        elif '0' <= char <= '9':
            result.append(f'x{char}')
        else:
            result.append(char)

    return ''.join(result)

from collections import namedtuple

def dict_to_namedtuple(d, nt_class):
    """
    Constructs an instance of the namedtuple class using values from the dictionary.
    Handles nested dictionaries by recursively converting them into nested namedtuples.

    :param d: Dictionary with keys matching the field names of the namedtuple class.
    :param nt_class: Namedtuple class with predefined field names.
    :return: An instance of nt_class with values from the dictionary d.
    """
    _fields = nt_class._fields
    kwargs = {}
    for field in _fields:
        if isinstance(d[field], dict):
            nt_field_class = namedtuple(field, d[field].keys())
            kwargs[field] = dict_to_namedtuple(d[field], nt_field_class)
        else:
            kwargs[field] = d[field]
    return nt_class(**kwargs)

def is_valid_parentheses(s):
    """
    Determines if the given string s is a valid parentheses string.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if s is a valid parentheses string, False otherwise.
    """
    matching_pairs = {
        ')': '(',
        '}': '{',
        ']': '['
    }
    stack = []

    for char in s:
        if char in matching_pairs:
            top_element = stack.pop() if stack else '#'
            if matching_pairs[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def prime_sieve(n):
    """
    Implements the Sieve of Eratosthenes algorithm to generate all prime numbers less than n.

    Parameters:
    n (int): The upper limit (exclusive) to find prime numbers.

    Returns:
    list: A list of all prime numbers less than n.
    """
    if n <= 2:
        return []

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    primes = [2]

    for start in range(3, int(n ** 0.5) + 1, 2):
        if is_prime[start]:
            for multiple in range(start*start, n, start*2):
                is_prime[multiple] = False

    for num in range(3, n, 2):
        if is_prime[num]:
            primes.append(num)

    return primes

def length_of_longest_substring(s: str) -> int:
    """
    Finds the length of the longest substring without repeating characters.

    :param s: The input string.
    :return: The length of the longest substring without repeating characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        else:
            longest = max(longest, i - start + 1)

        char_index_map[char] = i

    return longest

def escape_special_characters(input_string):
    """
    Escapes special characters and non-ASCII characters in the input string.

    Parameters:
    input_string (str): The string to be processed.

    Returns:
    str: The processed string with special characters and non-ASCII characters escaped.
    """
    escaped_chars = {
        "'": "''",
        '"': '""',
        '\\': '\\\\',
        '\0': '\\0'
    }

    result = []

    for char in input_string:
        if char in escaped_chars:
            result.append(escaped_chars[char])
        elif ord(char) > 127:
            result.append(f'\\u{ord(char):04x}')
        else:
            result.append(char)

    return ''.join(result)

