def move_character(current_position, direction):
    """
    Moves the character in the specified direction on a 10x10 grid.

    Parameters:
    - current_position: A tuple (row, column) representing the current position.
    - direction: A string ("up", "down", "left", "right") representing the direction of movement.

    Returns:
    - A tuple (new_row, new_col) representing the new position after the movement.
    """
    row, col = current_position
    moves = {
        "up": (-1, 0),
        "down": (1, 0),
        "left": (0, -1),
        "right": (0, 1)
    }

    if direction in moves:
        move_row, move_col = moves[direction]
    else:
        return current_position

    new_row = row + move_row
    new_col = col + move_col

    if 0 <= new_row < 10 and 0 <= new_col < 10:
        return (new_row, new_col)
    else:
        return current_position

def roman_to_integer(roman):
    """
    Convert a Roman numeral string to its integer value.

    :param roman: A string representing a Roman numeral.
    :return: An integer representing the value of the Roman numeral.
    """
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    num = 0
    prev_value = 0

    for char in reversed(roman):
        value = roman_map[char]
        if value < prev_value:
            num -= value
        else:
            num += value
        prev_value = value

    return num

