def hex_to_rgb(hex_color):
    """
    Convert a hexadecimal color code to an RGB tuple.

    Parameters:
    hex_color (str): A string representing a hexadecimal color code in the format #RRGGBB.

    Returns:
    tuple: A tuple (R, G, B) where R, G, and B are integers in the range [0, 255].
    """
    if hex_color.startswith('#') and len(hex_color) == 7:
        hex_color = hex_color[1:]  # Remove the '#' character
    else:
        raise ValueError("Hex color code must be in the format #RRGGBB")

    def hex_digit_to_decimal(digit):
        if '0' <= digit <= '9':
            return ord(digit) - ord('0')
        elif 'A' <= digit <= 'F':
            return ord(digit) - ord('A') + 10
        elif 'a' <= digit <= 'f':
            return ord(digit) - ord('a') + 10
        else:
            raise ValueError("Invalid hexadecimal digit")

    r = hex_digit_to_decimal(hex_color[0]) * 16 + hex_digit_to_decimal(hex_color[1])
    g = hex_digit_to_decimal(hex_color[2]) * 16 + hex_digit_to_decimal(hex_color[3])
    b = hex_digit_to_decimal(hex_color[4]) * 16 + hex_digit_to_decimal(hex_color[5])

    return (r, g, b)

def find_primes_below(n):
    """
    Returns a list of all prime numbers less than a given number n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit (exclusive) for finding prime numbers.
    :return: A list of prime numbers less than n.
    """
    if n <= 2:
        return []

    prime = [True] * n
    p = 2
    while p * p < n:
        if prime[p]:
            for i in range(p * p, n, p):
                prime[i] = False
        p += 1

    return [p for p in range(2, n) if prime[p]]

def apply_operations(number, operations):
    """
    Apply a sequence of operations to a number and return intermediate results.

    :param number: Initial integer number to apply operations on.
    :param operations: List of tuples, each containing an operation type and a value.
    :return: List of intermediate results after each operation.
    :raises ValueError: If a division by zero is attempted.
    """
    results = []
    for operation, value in operations:
        if operation == "add":
            number += value
        elif operation == "multiply":
            number *= value
        elif operation == "subtract":
            number -= value
        elif operation == "divide":
            if value != 0:
                number /= value
            else:
                raise ValueError("Division by zero is not allowed.")
        results.append(number)
    return results

def can_partition(nums):
    """
    Determines if a list of non-negative integers can be partitioned into two subsets
    with equal sum.

    :param nums: List of non-negative integers
    :return: True if the list can be partitioned into two subsets with equal sum, False otherwise
    """
    if len(nums) < 2:
        return False

    total_sum = sum(nums)

    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)

    dp = [[False] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if nums[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

def calculate_difficulty_level(age, experience):
    """
    Calculate the difficulty level of the game based on the player's age and experience.

    Parameters:
    age (int): The player's age.
    experience (int): The player's years of experience.

    Returns:
    int: The difficulty level (1 for Easy, 2 for Medium, 3 for Hard, 4 for Extreme).
    """
    if age > 25 and experience > 5:
        return 4  # Extreme
    elif age <= 10:
        return 1  # Easy
    elif 11 <= age <= 15:
        return 2  # Medium
    elif 16 <= age <= 20:
        return 3  # Hard
    else:
        return 4  # Extreme

import math
from itertools import combinations

def min_euclidean_distance(points):
    """
    Computes the Euclidean distance between the closest pair of points in a 2D plane.

    Parameters:
    points (list of tuples): A list where each tuple contains two integers representing the x and y coordinates of a point.

    Returns:
    float: The Euclidean distance between the closest pair of points, or None if there are fewer than two points.
    """
    if len(points) < 2:
        return None

    def distance(point1, point2):
        return math.sqrt((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2)

    min_dist = float('inf')
    for point1, point2 in combinations(points, 2):
        dist = distance(point1, point2)
        if dist < min_dist:
            min_dist = dist

    return min_dist

def flatten_dict(nested_dict):
    """
    Flattens a nested dictionary into a single-level dictionary with keys representing the path to each value.

    :param nested_dict: A dictionary that may contain nested dictionaries.
    :return: A flattened dictionary with keys as paths and values as the original values.
    """
    def is_dict(value):
        return isinstance(value, dict)

    flat_dict = {}
    stack = [(nested_dict, "")]

    while stack:
        current_dict, path = stack.pop()
        keys = []
        for key in current_dict:
            keys.append(key)
        i = 0
        while i < len(keys):
            key = keys[i]
            value = current_dict[key]
            if is_dict(value):
                new_path = path + key + "." if path else key + "."
                stack.append((value, new_path))
            else:
                new_path = path + key if path else key
                flat_dict[new_path] = value
            i += 1

    return flat_dict

from collections import defaultdict
from operator import itemgetter

def balanced_schedule(sessions):
    """
    Determines if a list of sessions is balanced, meaning no sessions of the same type overlap
    and all sessions are in chronological order.

    :param sessions: List of tuples, where each tuple contains (start_time, end_time, session_type)
    :return: True if the schedule is balanced, False otherwise
    """
    sessions_by_type = defaultdict(list)

    for session in sessions:
        sessions_by_type[session[2]].append(session)

    for key in sessions_by_type:
        sessions_by_type[key] = sorted(sessions_by_type[key], key=itemgetter(0))

    for key in sessions_by_type:
        for i in range(1, len(sessions_by_type[key])):
            if sessions_by_type[key][i][0] < sessions_by_type[key][i-1][1]:
                return False

    return True

def remove_file_extension(filename):
    """
    Removes the file extension from the given filename if it ends with one of the known extensions.

    Parameters:
    filename (str): The name of the file.

    Returns:
    str: The filename with the extension removed, if applicable.
    """
    extensions = {'.txt', '.pdf', '.jpg', '.png', '.npz'}
    for ext in extensions:
        if filename.endswith(ext):
            return filename[:-len(ext)]
    return filename

