def deserialise(byte_input):
    """
    Converts a bytes object representing an integer in decimal, hexadecimal, or binary format
    back into the corresponding integer. Returns None if the input is not a valid integer representation.

    :param byte_input: bytes object representing an integer
    :return: integer or None
    """
    try:
        str_input = byte_input.decode('utf-8').strip()
        if str_input.startswith(('0x', '0X')):
            return int(str_input, 16)
        elif str_input.startswith(('0b', '0B')):
            return int(str_input, 2)
        else:
            return int(str_input)
    except (ValueError, UnicodeDecodeError):
        return None

def factorial_recursive(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the integer n.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial_recursive(n - 1)

def find_primes_below(limit):
    """
    Returns a list of all prime numbers below the given limit using the Sieve of Eratosthenes algorithm.

    :param limit: An integer representing the upper bound (exclusive) for finding prime numbers.
    :return: A list of prime numbers less than the limit.
    """
    if limit <= 2:
        return []

    is_prime = [True] * limit
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(limit**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, limit, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def find_mode(numbers):
    """
    Returns the mode of the list of integers, which is the integer that appears most frequently.
    If there are multiple integers with the same highest frequency, returns the smallest integer.
    Returns None if the list is empty.

    :param numbers: List of integers
    :return: Integer representing the mode or None if the list is empty
    """
    if not numbers:
        return None

    frequency = {}
    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    max_frequency = max(frequency.values())
    modes = [number for number, count in frequency.items() if count == max_frequency]

    return min(modes)

def find_common_prefix(strs):
    """
    Finds the longest common prefix among a list of strings.

    :param strs: List of strings to evaluate.
    :return: The longest common prefix, or an empty string if no common prefix exists.
    """
    if not strs:
        return ""

    prefix = strs[0]

    for string in strs[1:]:
        while string[:len(prefix)] != prefix and prefix:
            prefix = prefix[:-1]
        if not prefix:
            return ""

    return prefix

def findKthLargest(numbers, k):
    """
    Returns the k-th largest element in the array without using built-in sorting functions.
    If k is greater than the length of the array, returns None.

    :param numbers: List[int] - The list of integers.
    :param k: int - The k-th largest element to find.
    :return: int or None - The k-th largest element or None if k is invalid.
    """
    if k > len(numbers) or not numbers:
        return None

    def partition(arr, low, high):
        pivot = arr[high]
        i = low
        for j in range(low, high):
            if arr[j] > pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[high] = arr[high], arr[i]
        return i

    def quickselect(arr, low, high, k):
        if low == high:
            return arr[low]

        pivot_index = partition(arr, low, high)

        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(arr, low, pivot_index - 1, k)
        else:
            return quickselect(arr, pivot_index + 1, high, k)

    return quickselect(numbers, 0, len(numbers) - 1, k - 1)

def flatten_path(path):
    """
    Flattens a hierarchical file system path represented as a string or a list of segments.

    Args:
    path (str or list): The file path as a string with segments separated by dots or a list of segments.

    Returns:
    list: A list of segments representing the file path.
    """
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    if isinstance(path, str):
        return path.split(".") if path else []
    elif isinstance(path, list):
        return list(flatten(path))
    else:
        return []

def count_elements(start, stop, step):
    """
    Returns the number of elements in the sequence generated by range(start, stop, step).

    Parameters:
    start (int): The starting value of the sequence.
    stop (int): The stopping value of the sequence (exclusive).
    step (int): The step value between each element in the sequence.

    Returns:
    int: The number of elements in the sequence.

    Raises:
    ValueError: If step is zero.
    """
    if step == 0:
        raise ValueError("step cannot be zero.")
    elif step > 0:
        return max(0, (stop - start + step - 1) // step)
    else:
        return max(0, (stop - start + step + 1) // step)

def level_order_traversal(tree):
    """
    Perform a level order traversal of a binary tree represented as a nested dictionary.

    :param tree: A dictionary representing the root of the binary tree.
    :return: A list of lists, where each inner list contains the values of the nodes at a particular level.
    """
    if tree is None:
        return []
    result, queue = [], [tree]
    while queue:
        level_result = []
        for _ in range(len(queue)):
            node = queue.pop(0)
            level_result.append(node["value"])
            if node["left"] is not None:
                queue.append(node["left"])
            if node["right"] is not None:
                queue.append(node["right"])
        result.append(level_result)
    return result

import math

def compute_direction(polar_coords):
    """
    Determines the direction of a point given its polar coordinates (r, θ).

    Parameters:
    polar_coords (list): A list containing two floating-point numbers [r, θ].

    Returns:
    str: The direction of the point relative to the origin.
    """
    r, theta = polar_coords

    if r == 0:
        return "Origin"

    theta = theta % (2 * math.pi)

    if math.isclose(theta, 0):
        return "East"
    elif math.isclose(theta, math.pi / 2):
        return "North"
    elif math.isclose(theta, math.pi):
        return "West"
    elif math.isclose(theta, 3 * math.pi / 2):
        return "South"

    if 0 < theta < math.pi / 2:
        return "North-East"
    elif math.pi / 2 < theta < math.pi:
        return "North-West"
    elif math.pi < theta < 3 * math.pi / 2:
        return "South-West"
    elif 3 * math.pi / 2 < theta < 2 * math.pi:
        return "South-East"

