import math

def find_closest_color(target_color, color_list):
    """
    Finds the color in color_list that is closest to target_color based on Euclidean distance.

    :param target_color: A tuple of three integers (R, G, B) representing the target color.
    :param color_list: A list of tuples, each containing three integers representing the colors to compare.
    :return: A tuple of three integers representing the closest color.
    """
    def euclidean_distance(c1, c2):
        return math.sqrt((c1[0] - c2[0]) ** 2 + (c1[1] - c2[1]) ** 2 + (c1[2] - c2[2]) ** 2)

    return min(color_list, key=lambda c: euclidean_distance(target_color, c))

def find_target(A, target):
    """
    Finds the index of the target in a rotated sorted array of unique integers.

    Parameters:
    A (List[int]): The rotated sorted array.
    target (int): The integer to find in the array.

    Returns:
    int: The index of the target if it exists in the array, otherwise -1.
    """
    left, right = 0, len(A) - 1

    while left <= right:
        mid = (left + right) // 2

        if A[mid] == target:
            return mid

        # Check if the left half is sorted
        if A[left] <= A[mid]:
            if A[left] <= target <= A[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Otherwise, the right half must be sorted
        else:
            if A[mid] <= target <= A[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

from typing import List

def generate_primes(n: int) -> List[int]:
    """
    Generate a list of prime numbers up to and including n.

    :param n: The upper limit integer up to which primes are to be generated.
    :return: A list of prime numbers less than or equal to n.
    """
    if n < 2:
        return []
    primes = [2]
    for candidate in range(3, n + 1, 2):
        is_prime = True
        for prime in primes:
            if candidate % prime == 0:
                is_prime = False
                break
            if prime * prime > candidate:
                break
        if is_prime:
            primes.append(candidate)
    return primes

def reverse_list_recursive(lst):
