def validate_memory_size(memory_size):
    """
    Validates if the given memory size is a power of 2 and does not exceed 1 terabyte (TB).

    Parameters:
    memory_size (int or str): The memory size in bytes or a string with units (KB, MB, GB, TB).

    Returns:
    bool: True if the memory size is valid, False otherwise.
    """
    def to_bytes(size_str):
        units = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3, 'TB': 1024**4}
        number_str, unit_str = size_str[:-2], size_str[-2:].upper()
        if unit_str not in units:
            raise ValueError(f"Unknown unit: {unit_str}")
        try:
            number = float(number_str)
        except ValueError:
            raise ValueError(f"Invalid number: {number_str}")
        return int(number * units[unit_str])

    max_bytes = 1024**4  # 1 terabyte in bytes

    if isinstance(memory_size, str):
        try:
            memory_size = to_bytes(memory_size)
        except ValueError:
            return False

    if not isinstance(memory_size, int) or memory_size <= 0:
        return False

    return memory_size <= max_bytes and (memory_size & (memory_size - 1)) == 0

def has_balanced_parentheses(s):
    """
    Check if a string has balanced parentheses, brackets, and braces.

    :param s: A string containing characters '(', ')', '[', ']', '{', and '}'.
    :return: True if the string is balanced, False otherwise.
    """
    bracket_pairs = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in bracket_pairs.values():
            stack.append(char)
        elif char in bracket_pairs:
            if stack and stack[-1] == bracket_pairs[char]:
                stack.pop()
            else:
                return False

    return not stack

def generate_dict_with_unique_columns(column_names, values):
    """
    Generates a dictionary from column names and values, ensuring unique keys by appending an underscore and a unique index to duplicates.

    :param column_names: List of column names (strings).
    :param values: List of values corresponding to the column names.
    :return: Dictionary with unique column names as keys and corresponding values.
    :raises RuntimeError: If the lengths of column_names and values lists are not equal.
    """
    if len(column_names) != len(values):
        raise RuntimeError("The lengths of column names and values lists are not equal.")

    unique_column_dict = {}
    seen_names = {}

    for i, name in enumerate(column_names):
        original_name = name
        if name in seen_names:
            seen_names[name] += 1
            name = f"{original_name}_{seen_names[name]}"
        else:
            seen_names[name] = 0

        unique_column_dict[name] = values[i]

    return unique_column_dict

