def find_min_in_rotated_array(nums):
    """
    Finds the minimum element in a rotated sorted array of distinct integers.

    :param nums: List[int] - A rotated sorted array of distinct integers.
    :return: int - The minimum element in the array.
    """
    left, right = 0, len(nums) - 1

    if nums[left] < nums[right]:
        return nums[left]

    while left < right:
        mid = (left + right) // 2

        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    return nums[left]

def arabicToRoman(num):
    """
    Convert an integer to a Roman numeral using only while loops.

    Parameters:
    num (int): The integer to convert to a Roman numeral.

    Returns:
    str: The Roman numeral representation of the integer.
    """
    roman_numerals = ""
    while num > 0:
        while num >= 1000:
            roman_numerals += "M"
            num -= 1000
        while num >= 900:
            roman_numerals += "CM"
            num -= 900
        while num >= 500:
            roman_numerals += "D"
            num -= 500
        while num >= 400:
            roman_numerals += "CD"
            num -= 400
        while num >= 100:
            roman_numerals += "C"
            num -= 100
        while num >= 90:
            roman_numerals += "XC"
            num -= 90
        while num >= 50:
            roman_numerals += "L"
            num -= 50
        while num >= 40:
            roman_numerals += "XL"
            num -= 40
        while num >= 10:
            roman_numerals += "X"
            num -= 10
        while num >= 9:
            roman_numerals += "IX"
            num -= 9
        while num >= 5:
            roman_numerals += "V"
            num -= 5
        while num >= 4:
            roman_numerals += "IV"
            num -= 4
        while num >= 1:
            roman_numerals += "I"
            num -= 1
    return roman_numerals

def is_valid_ip(ip_address: str) -> bool:
