    return True

def optimize_prime_check(n):
    """
    Determines if a given integer n is a prime number using an optimized algorithm.

    Parameters:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_most_frequent_word(text):
    """
    Returns the most frequently occurring word in the input string.
    If there are multiple words with the same highest frequency, returns the first one encountered.
    Handles invalid inputs by returning None.

    :param text: The input string.
    :return: The most frequent word or None if input is invalid.
    """
    if not isinstance(text, str) or not text.strip():
        return None

    text = text.lower()
    words = text.split()
    word_count = {}

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    most_frequent_word = None
    max_count = 0

    for word, count in word_count.items():
        if count > max_count:
            max_count = count
            most_frequent_word = word

    return most_frequent_word

def merge_dicts(dict1, dict2):
    """
    Merges two dictionaries into one. In case of key collisions, values from dict2 overwrite dict1.
    Handles nested dictionaries and lists.

    :param dict1: First dictionary to merge.
    :param dict2: Second dictionary to merge, overwriting values from dict1 in case of key collisions.
    :return: Merged dictionary.
    """
    merged_dict = dict1.copy()
    for key, val in dict2.items():
        if key in merged_dict:
            if isinstance(merged_dict[key], dict) and isinstance(val, dict):
                merged_dict[key] = merge_dicts(merged_dict[key], val)
            elif isinstance(merged_dict[key], list) and isinstance(val, list):
                merged_dict[key] = merged_dict[key] + val
            else:
                merged_dict[key] = val
        else:
            merged_dict[key] = val
    return merged_dict

