def flatten_json(data, parent_key='', sep='_'):
    """
    Flattens a JSON object (nested dictionaries and lists) into a flat dictionary.

    Args:
        data (dict/list): The JSON data to flatten.
        parent_key (str): The base key string that will be prepended to each subkey.
        sep (str): The separator to use between keys.

    Returns:
        dict: A flat dictionary with keys representing the path to each value in the original JSON.
    """
    items = []
    if isinstance(data, dict):
        for k, v in data.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            items.extend(flatten_json(v, new_key, sep=sep).items())
    elif isinstance(data, list):
        for i, item in enumerate(data):
            new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
            items.extend(flatten_json(item, new_key, sep=sep).items())
    else:
        items.append((parent_key, data))
    return dict(items)

def validate_version_number(version):
    """
    Validates whether the given string is a valid version number.

    A valid version number consists of one to three non-negative integers separated by dots.
    Each integer must be less than or equal to 65535, must not have leading zeros unless it is a single digit,
    and there must be no consecutive dots or leading/trailing dots.

    :param version: str - The version number string to validate.
    :return: bool - True if the version number is valid, False otherwise.
    """
    parts = version.split('.')

    if not 1 <= len(parts) <= 3:
        return False

    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        if part != str(int(part)):
            return False
        if int(part) > 65535:
            return False

    return True

def word_count(input_string: str) -> dict:
    """
    Returns a dictionary with each unique word from the input string as keys
    and their counts as values. The comparison is case-insensitive.

    :param input_string: A string containing words separated by spaces.
    :return: A dictionary with words as keys and their counts as values.
    """
    input_string = input_string.lower()
    words = input_string.split()
    word_counts = {}

    for word in words:
        if word in word_counts:
