def find_closest_timestamp(timestamps, current_time):
    """
    Returns the closest timestamp to current_time that is less than or equal to current_time.
    If no such timestamp exists, returns the smallest timestamp in the list.

    :param timestamps: List[int] - A sorted list of unique timestamps.
    :param current_time: int - The current time.
    :return: int - The closest timestamp to current_time that is less than or equal to current_time.
    """
    left, right = 0, len(timestamps) - 1

    if current_time < timestamps[left]:
        return timestamps[left]

    while left <= right:
        mid = (left + right) // 2
        if timestamps[mid] == current_time:
            return timestamps[mid]
        elif timestamps[mid] < current_time:
            left = mid + 1
        else:
            right = mid - 1

    return timestamps[right]

def validate_username(username: str) -> bool:
    """
    Validates a username based on specific rules:
    - Only alphanumeric characters, underscores, and periods are allowed.
    - No leading or trailing underscores or periods.
    - No consecutive underscores or periods.
    - No adjacent underscore-period or period-underscore combinations.
    - No sequence of more than three identical characters in a row.

    :param username: The username to validate.
    :return: True if the username is valid, False otherwise.
    """
    if not username:
        return False

    if username.startswith(('.', '_')) or username.endswith(('.', '_')):
        return False

    valid_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._"
    prev_char = ''
    repeat_count = 1

    for char in username:
        if char not in valid_chars:
            return False

        if char == prev_char and char in ('_', '.'):
            return False

        if (char, prev_char) in [('_', '.'), ('.', '_')]:
            return False

        if char == prev_char:
            repeat_count += 1
            if repeat_count > 3:
                return False
        else:
            repeat_count = 1

        prev_char = char

    return True

def count_odd_even_digits(n):
    """
    Returns a dictionary with the count of odd and even digits in the given integer n.

    Parameters:
    n (int): The integer to analyze.

    Returns:
    dict: A dictionary with keys 'odd' and 'even' representing the counts of odd and even digits.
    """
    if n == 0:
        return {'odd': 0, 'even': 1}

    counts = {'odd': 0, 'even': 0}
    n = abs(n)

    while n > 0:
        digit = n % 10
        if digit % 2 == 0:
            counts['even'] += 1
        else:
            counts['odd'] += 1
        n = n // 10

    return counts

import math

def sort_by_distance(points):
    """
    Sorts a list of 2D points based on their Euclidean distance from the origin (0, 0).

    Parameters:
    points (list of tuples): A list where each tuple contains two integers representing the coordinates of a point.

    Returns:
    list of tuples: A list of tuples sorted by their Euclidean distance from the origin.
    """
    def euclidean_distance(point):
        return math.sqrt(point[0]**2 + point[1]**2)

    return sorted(points, key=euclidean_distance)

def custom_uppercase(char):
    """Converts a single lowercase character to uppercase using ASCII value manipulation.
    If the character is not a lowercase letter, it is returned unchanged."""
