def trap(height):
    """
    Calculate the total amount of trapped rainwater given the heights of vertical lines.

    :param height: List[int] - A list of non-negative integers representing the heights of vertical lines.
    :return: int - The total amount of trapped rainwater.
    """
    if not height or len(height) < 2:
        return 0

    left, right = 0, len(height) - 1
    left_max, right_max = 0, 0
    water_trapped = 0

    while left < right:
        if height[left] < height[right]:
            if height[left] >= left_max:
                left_max = height[left]
            else:
                water_trapped += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]
            else:
                water_trapped += right_max - height[right]
            right -= 1

    return water_trapped

def find_duplicates(input_list):
    """
    Identifies all integers that appear more than once in the input list.

    Parameters:
    input_list (list of int): A list of integers.

    Returns:
    list of int: A list of integers that appear more than once in the input list, without duplicates.
    """
    element_count = {}
    duplicates = []

    for number in input_list:
        if number in element_count:
            element_count[number] += 1
        else:
            element_count[number] = 1

    for number, count in element_count.items():
        if count > 1:
            duplicates.append(number)

    return duplicates

def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than a given number n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit (exclusive) for finding prime numbers.
    :return: A list of prime numbers less than n.
    """
    if n < 2:
        return []

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def fibonacci_recursive_helper(num, memo=None):
    """
    Calculate the n-th Fibonacci number using recursion with memoization.

    :param num: The position in the Fibonacci sequence (0-indexed).
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: The n-th Fibonacci number.
    """
    if memo is None:
        memo = {}
    if num in memo:
        return memo[num]
    if num <= 1:
        return num
    memo[num] = fibonacci_recursive_helper(num - 1, memo) + fibonacci_recursive_helper(num - 2, memo)
    return memo[num]

def get_complementary_dna(dna_sequence):
    """
    Returns the complementary DNA sequence for a given DNA sequence.

    Parameters:
    dna_sequence (str): A string representing the DNA sequence.

    Returns:
    str: The complementary DNA sequence.

    Raises:
    ValueError: If the input contains any non-standard DNA bases.
    """
    complement = {'a': 't', 't': 'a', 'c': 'g', 'g': 'c'}
    complementary_sequence = []
    dna_sequence = dna_sequence.lower()

    for base in dna_sequence:
        if base in complement:
            complementary_sequence.append(complement[base])
        else:
            raise ValueError(f"Invalid base '{base}' found in DNA sequence. Only standard bases A, T, C, G are allowed.")

    return ''.join(complementary_sequence)

def find_k_smallest_elements(nums, k):
    """
    Returns the k smallest elements from the list nums without modifying the original list.
    If k is less than or equal to zero, or greater than the length of nums, returns an empty list.

    :param nums: List of integers
    :param k: Integer representing the number of smallest elements to return
    :return: List of k smallest integers from nums
    """
    if k <= 0 or not nums:
        return []
    elif k >= len(nums):
        return sorted(nums)
    else:
        return sorted(nums)[:k]

def find_primes(limit):
    """
    Returns a list of all prime numbers less than or equal to the given limit using the Sieve of Eratosthenes algorithm.

    :param limit: An integer representing the upper limit.
    :return: A list of prime numbers less than or equal to the limit.
    """
    if limit < 2:
        return []

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(limit**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, limit + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def isValidParentheses(s: str) -> bool:
    """
    Determines if the input string of parentheses is valid.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is valid, otherwise False.
    """
    stack = []
    parenthesis_map = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in parenthesis_map:
            top_element = stack.pop() if stack else "#"
            if parenthesis_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def find_longest_common_subsequence(str1, str2):
    """
    Returns the longest common subsequence of two input strings using dynamic programming.

    :param str1: First input string
    :param str2: Second input string
    :return: A string representing the longest common subsequence
    """
    m, n = len(str1), len(str2)
    dp = [['' for _ in range(n+1)] for _ in range(m+1)]

    for i in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + str1[i-1]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1], key=len)

    return dp[m][n]

def factorial_range(start, end):
    """
    Calculate the factorial of all numbers in the range [start, end] (both inclusive)
    and return a dictionary with numbers as keys and their factorials modulo 1,000,000,007 as values.

    :param start: The starting integer of the range.
    :param end: The ending integer of the range.
    :return: A dictionary with numbers as keys and their factorials modulo 1,000,000,007 as values.
    """
    MOD = 1_000_000_007
    result = {}

    if not isinstance(start, int) or not isinstance(end, int):
        return result

    if start < 0 or end < 0 or start > end:
        return result

    def factorial(n):
        fact = 1
        for i in range(2, n + 1):
            fact = (fact * i) % MOD
        return fact

    for num in range(start, end + 1):
        result[num] = factorial(num)

    return result

def findMinRotated(nums):
    """
    Finds the minimum element in a rotated sorted array that may contain duplicates.

    :param nums: List[int] - A rotated sorted array of integers that may contain duplicates.
    :return: int - The smallest element in the array.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = left + (right - left) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        elif nums[mid] < nums[right]:
            right = mid
        else:
            right -= 1

    return nums[left]

def word_frequency(strings):
    """
    Computes the frequency of each unique word in a list of strings.

    Parameters:
    strings (list of str): A list of strings, where each string consists of words separated by spaces.

    Returns:
    dict: A dictionary with words as keys and their frequencies as values.
    """
    frequency_dict = {}
    for string in strings:
        words = string.split()
        for word in words:
            if word in frequency_dict:
                frequency_dict[word] += 1
            else:
                frequency_dict[word] = 1
    return frequency_dict

def capitalize_words(s):
    """
    Capitalizes the first letter of each word in the given string `s`.

    Parameters:
    s (str): The input string to be processed.

    Returns:
    str: A new string with the first letter of each word capitalized and the rest in lowercase.
    """
    result = []
    capitalize_next = True  # This flag decides whether to capitalize the next letter

    for char in s:
        if char.isalpha():
            if capitalize_next:
                result.append(char.upper())
                capitalize_next = False
            else:
                result.append(char.lower())
        else:
            result.append(char)
            capitalize_next = True  # Reset flag if the current character is not a letter

    return ''.join(result)

def flatten_json(y):
