    Flattens a nested dictionary into a one-level dictionary with dot-separated keys.

    :param y: A dictionary representing a JSON object.
    :return: A flattened dictionary with dot-separated keys.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

