def validate_parentheses(s):
    """
    Checks if a string s containing only parentheses '()' has balanced parentheses.

    :param s: A string consisting of '(' and ')'.
    :return: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def calculate_average_scores(student_scores):
