def transform_list(lst, dct):
    """
    Transforms a nested list of strings based on a given dictionary mapping.

    Parameters:
    lst (list): A nested list of strings to be transformed.
    dct (dict): A dictionary mapping strings to their replacements.

    Returns:
    list: A new list with transformations applied according to dct.
    """
    def transform_element(element):
        if isinstance(element, list):
            return [transform_element(sub_element) for sub_element in element]
        elif isinstance(element, str):
            return dct.get(element, "-")
        else:
            return "-"

    return transform_element(lst)

def optimize_primes(limit):
    """
    Returns a list of all prime numbers up to and including the given limit using the Sieve of Eratosthenes algorithm.

    :param limit: The upper bound up to which prime numbers are to be found.
    :return: A list of prime numbers up to and including the limit.
    """
    if limit < 2:
        return []

    is_prime = [True] * (limit + 1)
    p = 2
    while p * p <= limit:
        if is_prime[p]:
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1

    return [p for p in range(2, limit + 1) if is_prime[p]]

def find_min_max(numbers):
    """
    Returns a tuple containing the minimum and maximum values from the list.

    :param numbers: List of integers
    :return: Tuple (min_value, max_value)
    :raises ValueError: If the input list is empty
    """
    if not numbers:
        raise ValueError("The input list must not be empty.")

    min_val = max_val = numbers[0]

    for num in numbers[1:]:
        if num < min_val:
            min_val = num
        elif num > max_val:
            max_val = num

    return (min_val, max_val)

def combine_elements(a, b):
    """
    Combines two lists into one and sorts it in descending order if both lists are numeric.

    Parameters:
    a (list): The first list.
    b (list): The second list.

    Returns:
    list: A new list containing all elements from a and b, sorted in descending order if both are numeric.

    Raises:
    ValueError: If either a or b contains non-numeric elements.
    """
    def is_list_of_numbers(lst):
        return all(isinstance(i, (int, float)) for i in lst)

    if isinstance(a, list) and isinstance(b, list) and is_list_of_numbers(a) and is_list_of_numbers(b):
        return sorted(a + b, reverse=True)
    else:
        raise ValueError("Both inputs must be lists of numbers")

def swap_keys_values(input_dict):
    """
    Swaps the keys and values of the input dictionary.
    If there are duplicate values, returns an empty dictionary.

    :param input_dict: Dictionary with unique keys and integer values.
    :return: A new dictionary with keys and values swapped, or an empty dictionary if duplicates are found.
    """
    swapped_dict = {}
    seen_values = set()

    for key, value in input_dict.items():
        if value in seen_values:
            return {}
        seen_values.add(value)
        swapped_dict[value] = key

    return swapped_dict

def process_logs(logs):
