    :param logs: List of log entries, each a string in the format 'timestamp log_level message'.
    :return: Dictionary mapping each log level to its count.
    """
    log_level_counts = {}
    for log in logs:
        parts = log.split()
        log_level = parts[1]
        if log_level in log_level_counts:
            log_level_counts[log_level] += 1
        else:
            log_level_counts[log_level] = 1
    return log_level_counts

def deep_copy(data):
    """
    Creates a deep copy of the given data structure, which can be a list, dictionary, or a combination of both.

    :param data: The data structure to be copied.
    :return: A deep copy of the input data structure.
    """
    if isinstance(data, dict):
        new_data = {}
        for key, value in data.items():
            new_data[key] = deep_copy(value)
        return new_data
    elif isinstance(data, list):
        new_data = []
        for item in data:
            new_data.append(deep_copy(item))
        return new_data
    else:
        return data  # Return the data as it is for immutable types (int, str, float, etc.)

def group_elements(lst):
