    Constructs a dictionary where keys are unique elements from the list,
    and values are lists of indices where these elements appear.

    :param lst: List of integers
    :return: Dictionary with elements as keys and lists of indices as values
    """
    result = {}
    for index, value in enumerate(lst):
        if value not in result:
            result[value] = []
        result[value].append(index)
    return result

def first_non_none(lst, default=None):
    """
    Returns the first non-None value in the list. If all elements are None,
    returns the default value provided as an argument.

    :param lst: List of integers and None values.
    :param default: Default value to return if all elements are None.
    :return: First non-None value or the default value.
    """
    def helper(index):
        if index == len(lst):
            return default
        return lst[index] if lst[index] is not None else helper(index + 1)

    return helper(0)

def process_data(data):
