        else:
            averages[key] = 0
    return averages

def check_prime(num: int) -> bool:
    """
    Determines if the given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if num is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

