            'sentiment': classify_rating(review['rating'])
        }
        for review in reviews
    ]

from typing import List

def calculate_average_rating(ratings: List[int]) -> float:
    """
    Calculate the average rating from a list of user ratings.

    :param ratings: List of integers representing user ratings.
    :return: The average rating as a float. Returns 0.0 if the list is empty.
    """
    if not ratings:
        return 0.0
    return sum(ratings) / len(ratings)

def find_mode(numbers):
    """
    Finds the mode(s) of a list of integers.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    list: A list containing the mode(s) of the input list.
    """
    if not numbers:
        return []

    frequency = {}
    for num in numbers:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_count = max(frequency.values())
    modes = [num for num, count in frequency.items() if count == max_count]

    return modes

def count_occurrences(numbers):
    """
    Returns a dictionary with each integer from the list as a key and its count as the value.

    :param numbers: List of integers
    :return: Dictionary with integers as keys and their counts as values
    """
    occurrence_dict = {}
    for number in numbers:
        if number in occurrence_dict:
            occurrence_dict[number] += 1
        else:
            occurrence_dict[number] = 1
    return occurrence_dict

def filter_ascii_strings(strings):
    """
    Filters a list of strings, returning only those that can be decoded using ASCII encoding.
    Non-alphabetic characters are removed from successfully decoded strings.

    :param strings: List of strings to be processed.
    :return: List of strings after processing.
    """
    def is_ascii(s):
        try:
            s.encode('ascii').decode('ascii')
            return True
        except UnicodeEncodeError:
            return False

    def remove_non_alphabetic(s):
        return ''.join(filter(str.isalpha, s))

    result = []
    for s in strings:
        if is_ascii(s):
            result.append(remove_non_alphabetic(s))
        else:
            result.append('')

    return result

def longest_common_prefix(strings):
    """
    Finds the longest common prefix among all strings in the given list.

    :param strings: List of strings to find the common prefix for.
    :return: The longest common prefix as a string, or an empty string if no common prefix exists.
    """
    if not strings:
        return ""

    prefix = strings[0]
    for s in strings[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def format_status(status, show_all=False):
    """
    Formats the system status parameters into a human-readable string.

    Parameters:
    status (dict): A dictionary with keys as parameter names and values as their status.
    show_all (bool): If True, includes all parameters; otherwise, includes only those with True, None, or positive integers.

    Returns:
    str: A formatted string of the status parameters.
    """
    formatted_status = []

    for key, value in status.items():
        if not show_all and (value is False or value == 0):
            continue

        if value is True:
            display_value = '✓'
        elif value is False:
            display_value = '✗'
        elif value is None:
            display_value = '-'
        elif isinstance(value, int):
            display_value = str(value)
        else:
            display_value = str(value)

        formatted_status.append(f"{key}: {display_value}")

    return "\n".join(formatted_status)

from typing import List, Optional

def find_target(numbers: List[int], target: int) -> Optional[int]:
    """
    Perform a binary search to find the index of the first occurrence of the target in a sorted list.

    :param numbers: List of sorted integers.
    :param target: The integer to search for.
    :return: The index of the first occurrence of the target, or None if the target is not found.
    """
    left, right = 0, len(numbers) - 1
    while left <= right:
        mid = (left + right) // 2
        if numbers[mid] == target:
            if mid == 0 or numbers[mid - 1] != target:
                return mid
            right = mid - 1
        elif numbers[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return None

def kth_smallest_element(arr, k):
    """
    Find the k-th smallest element in the list without using built-in sorting functions.

    Parameters:
    arr (list of int): The list of integers.
    k (int): The k-th position to find the smallest element for.

    Returns:
    int: The k-th smallest element in the list.
    """
    def partition(low, high):
        pivot = arr[high]
        i = low
        for j in range(low, high):
            if arr[j] < pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[high] = arr[high], arr[i]
        return i

    def quickselect(low, high, k):
        if low == high:
            return arr[low]

        pivot_index = partition(low, high)

        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(low, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, high, k)

    if 1 <= k <= len(arr):
        return quickselect(0, len(arr) - 1, k - 1)
    else:
        return None

def recursive_fibonacci(n):
    """
    Compute the n-th Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The n-th Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return recursive_fibonacci(n - 1) + recursive_fibonacci(n - 2)

def find_pair(numbers, target_sum):
    """
    Finds a pair of integers in the list that add up to the target_sum.

    :param numbers: List of integers.
    :param target_sum: Integer representing the target sum.
    :return: Tuple of two integers that add up to target_sum, or None if no such pair exists.
    """
    number_dict = {}
    for number in numbers:
        complement = target_sum - number
        if complement in number_dict:
            return (complement, number)
        number_dict[number] = True
    return None

def is_valid_parentheses_sequence(parens_list):
    """
    Determines if each string in the list represents a valid sequence of nested parentheses.

    :param parens_list: List of strings, each containing only '(', ')', '[', ']', '{', '}'.
    :return: List of booleans indicating if each string is a valid sequence.
    """
    def is_valid(parens):
        """
        Checks if a single string of parentheses is valid.

        :param parens: String containing only '(', ')', '[', ']', '{', '}'.
        :return: Boolean indicating if the string is a valid sequence.
        """
        stack = []
        matching_bracket = {')': '(', ']': '[', '}': '{'}
        for char in parens:
            if char in matching_bracket.values():
                stack.append(char)
            elif char in matching_bracket:
                if not stack or stack[-1] != matching_bracket[char]:
                    return False
                stack.pop()
            else:
                return False
        return not stack

    return [is_valid(parens) for parens in parens_list]

def find_best_score(scores):
    """
    Finds the highest and second-highest distinct scores from a list of scores.
    If there are fewer than two distinct scores, returns the highest score repeated twice.

    :param scores: List of integers representing the scores.
    :return: A tuple of two integers (highest_score, second_highest_score).
    """
    unique_scores = list(set(scores))
    unique_scores.sort(reverse=True)

    if len(unique_scores) < 2:
        return (unique_scores[0], unique_scores[0])
    else:
        return (unique_scores[0], unique_scores[1])

def format_student_records(student_records):
