def parse_and_format(input_string):
    """
    Parses a string representing a list of integers enclosed in square brackets and returns a new string
    with the integers separated by commas and no whitespace characters. Returns an empty string if the
    input is malformed.

    :param input_string: str - The input string to parse.
    :return: str - The formatted string of integers.
    """
    result = ""
    i = 0
    length = len(input_string)

    while i < length and (input_string[i] == ' ' or input_string[i] == '\t' or input_string[i] == '\n'):
        i += 1

    if i < length and input_string[i] == '[':
        i += 1
    else:
        return result

    while i < length and (input_string[i] == ' ' or input_string[i] == '\t' or input_string[i] == '\n'):
        i += 1

    need_comma = False

    while i < length:
        if input_string[i] == ']':
            break
        elif not (input_string[i] == ' ' or input_string[i] == '\t' or input_string[i] == '\n'):
            num_start = i
            while i < length and (input_string[i].isdigit() or input_string[i] == '-'):
                i += 1

            num_end = i
            if need_comma:
                result += ','

            for j in range(num_start, num_end):
                result += input_string[j]

            need_comma = True
            i -= 1
        i += 1

    if i < length and input_string[i] == ']':
        return result
    else:
        return result

def calculate_emission_probabilities(emission_counts):
    """
    Calculate the emission probabilities for each state based on the given emission counts.

    :param emission_counts: A dictionary where keys are states and values are dictionaries mapping emissions to their counts.
    :return: A dictionary where keys are states and values are dictionaries mapping emissions to their probabilities.
    """
    emission_probabilities = {}

    for state, emissions in emission_counts.items():
        total_count = 0
        probabilities = {}

        for emission, count_list in emissions.items():
            count = count_list[0]
            total_count += count
            probabilities[emission] = count

        if total_count > 0:
            for emission in probabilities:
                probabilities[emission] /= total_count
        else:
            for emission in probabilities:
                probabilities[emission] = 0

        emission_probabilities[state] = probabilities

    return emission_probabilities

def find_key_in_dict(data, key):
    """
    Recursively searches for a key in a nested dictionary and returns the corresponding value.

    Parameters:
    data (dict): The dictionary to search within.
    key (str): The key to search for.

    Returns:
    The value associated with the key if found, otherwise None.
    """
    if not isinstance(data, dict) or not data:
        return None

    if key in data:
        return data[key]

    for k, v in data.items():
        if isinstance(v, dict):
            result = find_key_in_dict(v, key)
            if result is not None:
                return result

    return None

def closest_to_origin(coordinates):
    """
    Returns the coordinates of the point closest to the origin (0, 0) from a list of points.

    :param coordinates: List of tuples, where each tuple contains two integers representing the x and y coordinates.
    :return: Tuple of two integers representing the x and y coordinates of the closest point.
    """
    if not coordinates:
        return None  # Handle the edge case with an empty list
    return min(coordinates, key=lambda point: point[0]**2 + point[1]**2)

def process_data(data_dict):
    """
    Processes a dictionary of lists of integers, returning a dictionary of statistics.

    Parameters:
    data_dict (dict): A dictionary where each key is a string and each value is a list of integers.

    Returns:
    dict: A dictionary where each key maps to another dictionary containing 'sum', 'average', 'min', and 'max'.
          If the list is empty, the value is an empty dictionary.
    """
    result = {}

    for key, values in data_dict.items():
        if not values:
            result[key] = {}
        else:
            total_sum = sum(values)
            total_count = len(values)
            average = total_sum / total_count
            minimum = min(values)
            maximum = max(values)

            result[key] = {
                'sum': total_sum,
                'average': average,
                'min': minimum,
                'max': maximum
            }

    return result

def detect_cycle(graph):
    """
    Detects if there is a cycle in a directed graph represented as an adjacency list.

    :param graph: A dictionary representing the graph where each key is a vertex and its value is a list of adjacent vertices.
    :return: True if the graph contains a cycle, False otherwise.
    """
    def dfs(node, visited, recursion_stack):
        visited[node] = True
        recursion_stack[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, recursion_stack):
                    return True
            elif recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        return False

    V = len(graph)
    visited = [False] * V
    recursion_stack = [False] * V

    for node in range(V):
        if not visited[node]:
            if dfs(node, visited, recursion_stack):
                return True
    return False

def convert_zone_to_code(zone):
    """
    Converts a zone string to an integer based on specific rules.

    Parameters:
    zone (str): The zone string to be converted.

    Returns:
    int or None: The converted integer or None if the zone does not match any rule.
    """
    def is_lucas_number(n):
        """Check if a number is a Lucas number less than 50."""
        lucas_numbers = {2, 1, 3, 4, 7, 11, 18, 29, 47}
        return n in lucas_numbers

    zone = zone.strip()

    if zone in ["Main Zone", "Main_Zone", "MZ"]:
        return 0
    elif "active" in zone.lower():
        return -1
    elif zone.startswith("Zone_") or zone.startswith("Zone"):
        try:
            num = int(zone[5:] if zone.startswith("Zone_") else zone[4:])
            if is_lucas_number(num) and num < 50:
                return -num
            return num
        except ValueError:
            return None
    elif 'A' <= zone[0] <= 'D':
        return -ord(zone[0])
    elif zone.isdigit() and 1 <= int(zone) <= 9:
        return int(zone)

    return None

def process_movie_metadata(metadata):
    """
    Processes movie metadata to ensure unique string values in lists, 
    while allowing duplicate numerical values. Non-list values are added directly.

    :param metadata: Dictionary containing movie metadata.
    :return: Processed dictionary with unique string values in lists.
    """
    processed_metadata = {}

    for key, value in metadata.items():
        if isinstance(value, list):
            unique_values = []
            for item in value:
                if isinstance(item, (int, float)):
                    unique_values.append(item)
                elif isinstance(item, str):
                    if item not in unique_values:
                        unique_values.append(item)
            processed_metadata[key] = unique_values
        else:
            processed_metadata[key] = value

    return processed_metadata

def optimized_fibonacci(n, memo=None):
    """
    Computes the nth Fibonacci number using memoization to optimize the computation.

    Parameters:
    n (int): The position in the Fibonacci sequence (non-negative integer).
    memo (dict): A dictionary to store previously computed Fibonacci numbers.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = optimized_fibonacci(n-1, memo) + optimized_fibonacci(n-2, memo)
        return memo[n]

from collections.abc import Iterable, Hashable

def deep_compare(obj1, obj2, visited=None):
    """
    Recursively compares two objects to determine if they are deeply equal,
    handling nested structures and circular references.

    :param obj1: First object to compare.
    :param obj2: Second object to compare.
    :param visited: Set of visited object pairs to handle circular references.
    :return: True if the objects are deeply equal, False otherwise.
    """
    if visited is None:
        visited = set()

    id_obj1, id_obj2 = id(obj1), id(obj2)

    if (id_obj1, id_obj2) in visited:
        return True

    visited.add((id_obj1, id_obj2))

    if type(obj1) != type(obj2) or (isinstance(obj1, Hashable) and isinstance(obj2, Hashable) and hash(obj1) != hash(obj2)):
        return False

    if isinstance(obj1, dict):
        if obj1.keys() != obj2.keys() or any(not deep_compare(obj1[key], obj2[key], visited) for key in obj1):
            return False
        return True

    if isinstance(obj1, Iterable) and not isinstance(obj1, (str, bytes)):
        obj1_iter, obj2_iter = iter(obj1), iter(obj2)
        try:
            while True:
                item1, item2 = next(obj1_iter), next(obj2_iter)
                if not deep_compare(item1, item2, visited):
                    return False
        except StopIteration:
            return True

    return obj1 == obj2

def sum_of_multiples(n):
    """
    Calculate the sum of all distinct multiples of 3 or 5 below a given number n.

    :param n: The upper limit (exclusive) for finding multiples.
    :return: The sum of all distinct multiples of 3 or 5 below n.
    """
    def arithmetic_sum(divisor):
        p = (n - 1) // divisor
        return divisor * p * (p + 1) // 2

    return arithmetic_sum(3) + arithmetic_sum(5) - arithmetic_sum(15)

def sum_dict_elements(input_dict):
    """
    Returns a tuple containing the sum of all keys and the sum of all values in the dictionary.
    If the dictionary contains the key-value pair (0, 0), returns None.

    :param input_dict: Dictionary with integer keys and values
    :return: Tuple of sums or None
    """
    items = list(input_dict.items())

    def recursive_sum(lst, index=0, sum_keys=0, sum_values=0):
        if index == len(lst):
            return (sum_keys, sum_values)

        key, value = lst[index]

        if key == 0 and value == 0:
            return None

        return recursive_sum(lst, index + 1, sum_keys + key, sum_values + value)

    return recursive_sum(items)

def find_common_indices(list1, list2, list3):
    """
    Returns a list of indices that are common in all three input lists.

    :param list1: List of unique integers.
    :param list2: List of unique integers.
    :param list3: List of unique integers.
    :return: List of integers common to list1, list2, and list3.
    """
    common_indices = []

    for i in list1:
        found_in_list2 = False
        for j in list2:
            if i == j:
                found_in_list2 = True
                break

        if not found_in_list2:
            continue

        found_in_list3 = False
        for k in list3:
            if i == k:
                found_in_list3 = True
                break

        if found_in_list3:
            common_indices.append(i)

    return common_indices

def flatten_list_of_dicts(list_of_dicts):
    """
    Flattens a list of dictionaries into a single dictionary where each key maps to a list of values
    from all dictionaries that share the same key.

    :param list_of_dicts: List of dictionaries to be flattened.
    :return: A dictionary with keys from all input dictionaries and values as lists of corresponding values.
    """
    result = {}
    for dictionary in list_of_dicts:
        for key, value in dictionary.items():
            if key in result:
                result[key].append(value)
            else:
                result[key] = [value]
    return result

def convert_data_structure(data):
    """
    Recursively converts a nested data structure by converting integers to strings,
    floats to truncated integers, and strings to their trimmed length.

    :param data: A nested data structure containing integers, floats, strings, lists, tuples, and dictionaries.
    :return: A new data structure with the same structure but with converted values.
    """
    if isinstance(data, int):
        return str(data)
    elif isinstance(data, float):
        return int(data)
    elif isinstance(data, str):
        return len(data.strip())
    elif isinstance(data, list):
        return [convert_data_structure(item) for item in data]
    elif isinstance(data, tuple):
        return tuple(convert_data_structure(item) for item in data)
    elif isinstance(data, dict):
        return {key: convert_data_structure(value) for key, value in data.items()}
    else:
        raise TypeError("Unsupported data type")

def translate_keys(input_dict, mapping):
    """
    Translates the keys of a nested dictionary according to a given mapping dictionary.

    Parameters:
    input_dict (dict): The dictionary whose keys are to be translated.
    mapping (dict): The dictionary containing the key mappings.

    Returns:
    dict: A new dictionary with translated keys.
    """
    def _translate(obj):
        if isinstance(obj, dict):
            return {mapping.get(k, k): _translate(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_translate(item) for item in obj]
        else:
            return obj

    return _translate(input_dict)

def flatten_tree(nested_list):
    """
    Perform a preorder traversal of a binary tree represented as a nested list.

    :param nested_list: A nested list representing a binary tree.
    :return: A list of integers representing the preorder traversal of the tree.
    """
    def preorder_traversal(node):
        if isinstance(node, list):
            for child in node:
                yield from preorder_traversal(child)
        else:
            yield node

    return list(preorder_traversal(nested_list))

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given in infix notation.

    :param expression: A string representing the mathematical expression.
    :return: A float representing the evaluated result of the expression.
    """
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] in '0123456789':
            val = 0
            while i < len(expression) and expression[i] in '0123456789':
                val = (val * 10) + int(expression[i])
                i += 1
            values.append(val)
            i -= 1
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        else:
            while (operators and operators[-1] != '(' and 
                   precedence(operators[-1]) >= precedence(expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

def time_to_seconds(time_str):
    """
    Converts a time duration in the format 'HH:MM:SS' to the total number of seconds.

    Parameters:
    time_str (str): A string representing time in the format 'HH:MM:SS'.

    Returns:
    int or None: The total number of seconds if the input is valid, otherwise None.
    """
    if len(time_str) != 8 or time_str[2] != ':' or time_str[5] != ':':
        return None

    hours = 0
    minutes = 0
    seconds = 0

    if '0' <= time_str[0] <= '9' and '0' <= time_str[1] <= '9':
        hours = (ord(time_str[0]) - ord('0')) * 10 + (ord(time_str[1]) - ord('0'))
    else:
        return None

    if '0' <= time_str[3] <= '9' and '0' <= time_str[4] <= '9':
        minutes = (ord(time_str[3]) - ord('0')) * 10 + (ord(time_str[4]) - ord('0'))
    else:
        return None

    if '0' <= time_str[6] <= '9' and '0' <= time_str[7] <= '9':
        seconds = (ord(time_str[6]) - ord('0')) * 10 + (ord(time_str[7]) - ord('0'))
    else:
        return None

    if 0 <= hours <= 23 and 0 <= minutes <= 59 and 0 <= seconds <= 59:
        return hours * 3600 + minutes * 60 + seconds
    else:
        return None

def count_occurrences(nums):
    """
    Counts the occurrences of each integer in the list nums.

    Parameters:
    nums (list of int): The list of integers to count occurrences for.

    Returns:
    dict: A dictionary with integers as keys and their counts as values.
    """
    counts = {}
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1
    return counts

def word_frequency(input_string):
    """
    Returns a dictionary containing the frequency of each word in the input string.

    :param input_string: A string containing words separated by whitespace.
    :return: A dictionary with words as keys and their frequencies as values.
    """
    words = input_string.split()
    frequency = {}

    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

