def find_largest_prime(n):
    """
    Returns the largest prime number less than or equal to n.

    Parameters:
    n (int): A positive integer (2 ≤ n ≤ 10^6)

    Returns:
    int: The largest prime number less than or equal to n.
    """
    if n < 2:
        return None  # No primes less than 2

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    for p in range(n, 1, -1):
        if is_prime[p]:
            return p

    return None

def evaluate_expression(s):
    """
    Evaluates a mathematical expression given as a string and returns the result as a float.

    :param s: A string representing a mathematical expression.
    :return: A float representing the evaluated result of the expression.
    """
    def get_tokens(string):
        tokens = []
        buffer = ''
        i = 0
        while i < len(string):
            if string[i].isdigit():
                buffer += string[i]
            else:
                if buffer:
                    tokens.append(float(buffer))
                    buffer = ''
                if string[i] != ' ':
                    tokens.append(string[i])
            i += 1
        if buffer:
            tokens.append(float(buffer))
        return tokens

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left // right)  # floor division

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operators = []
    values = []
    tokens = get_tokens(s)
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if isinstance(token, float):
            values.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        else:
            while (operators and precedence(operators[-1]) >= precedence(token)):
                apply_operator(operators, values)
            operators.append(token)
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

def rock_paper_scissors(player1, player2):
    """
    Simulates a game of rock-paper-scissors between two players.

    Parameters:
    player1 (str): The choice of the first player ("rock", "paper", or "scissors").
    player2 (str): The choice of the second player ("rock", "paper", or "scissors").

    Returns:
    str: The result of the game ("Player 1 wins", "Player 2 wins", "Tie", or an error message for invalid input).
    """
    rules = {
        'rock': 'scissors',
        'scissors': 'paper',
        'paper': 'rock'
    }

    if player1 not in rules or player2 not in rules:
        return "Invalid input. Please choose between 'rock', 'paper', or 'scissors'."

    if player1 == player2:
        return "Tie"
    elif rules[player1] == player2:
        return "Player 1 wins"
    else:
        return "Player 2 wins"

def my_sum_list(numbers):
    """
    Computes the sum of all integers in the list up to, but not including,
    the first occurrence of the number 13. If 13 is not present, returns
    the sum of all integers in the list.

    :param numbers: List of integers
    :return: Sum of integers up to the first occurrence of 13
    """
    try:
        stop_index = numbers.index(13)
    except ValueError:
        return sum(numbers)

    return sum(numbers[:stop_index])

def smallestFactor(n):
    """
    Returns the smallest prime factor of a given number n.
    If n is prime, returns n itself.

    :param n: Integer, the number to find the smallest prime factor for.
    :return: Integer, the smallest prime factor of n.
    """
    if n == 1:
        return None
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return i
    return n  # Return the number itself if it is prime

def convert_temperatures(temperatures, source_unit, target_unit):
    """
    Convert a list of temperatures from source_unit to target_unit.

    Parameters:
    temperatures (list of float): List of temperatures to convert.
    source_unit (str): The unit of the input temperatures ('Celsius', 'Fahrenheit', 'Kelvin').
    target_unit (str): The unit to which the temperatures should be converted ('Celsius', 'Fahrenheit', 'Kelvin').

    Returns:
    list of float: List of converted temperatures.

    Raises:
    ValueError: If an invalid unit is provided.
    """
    def celsius_to_fahrenheit(c):
        return (c * 9/5) + 32

    def celsius_to_kelvin(c):
        return c + 273.15

    def fahrenheit_to_celsius(f):
        return (f - 32) * 5/9

    def fahrenheit_to_kelvin(f):
        return (f - 32) * 5/9 + 273.15

    def kelvin_to_celsius(k):
        return k - 273.15

    def kelvin_to_fahrenheit(k):
        return (k - 273.15) * 9/5 + 32

    unit_conversion = {
        'Celsius': {
            'Fahrenheit': celsius_to_fahrenheit,
            'Kelvin': celsius_to_kelvin
        },
        'Fahrenheit': {
            'Celsius': fahrenheit_to_celsius,
            'Kelvin': fahrenheit_to_kelvin
        },
        'Kelvin': {
            'Celsius': kelvin_to_celsius,
            'Fahrenheit': kelvin_to_fahrenheit
        }
    }

    if source_unit not in unit_conversion:
        raise ValueError(f"Invalid source unit: {source_unit}")
    if target_unit not in unit_conversion:
        raise ValueError(f"Invalid target unit: {target_unit}")
    if source_unit == target_unit:
        return temperatures

    conversion_fn = unit_conversion[source_unit].get(target_unit)
    if conversion_fn is None:
        raise ValueError(f"Conversion from {source_unit} to {target_unit} is not supported")

    return [conversion_fn(temp) for temp in temperatures]

def find_all_prime_factors(n):
    """
    Returns a list of all distinct prime factors of the given integer n in ascending order.

    :param n: Integer, the number to find prime factors for.
    :return: List of integers, the distinct prime factors of n.
    """
    def prime_factors(n):
        i = 2
        factors = set()
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.add(i)
        if n > 1:
            factors.add(n)
        return factors

    return sorted(prime_factors(n))

