def calculate_gpa(grades):
    """
    Calculate the GPA for each student based on their grades.

    Parameters:
    grades (dict): A dictionary where keys are student IDs and values are lists of grades.

    Returns:
    dict: A dictionary with student IDs as keys and their calculated GPA as values, rounded to two decimal places.
    """
    gpa_dict = {}
    for student_id, grades_list in grades.items():
        if grades_list:
            gpa = sum(grades_list) / len(grades_list)
            gpa_dict[student_id] = round(gpa, 2)
        else:
            gpa_dict[student_id] = 0.0
    return gpa_dict

def dict_to_json_string(data):
    """
    Converts a list of dictionaries into a JSON-like string representation.

    :param data: List of dictionaries, each containing 'name', 'age', and 'grades'.
    :return: A string formatted as a JSON array of objects.
    """
    def handle_value(value):
        if isinstance(value, str):
            return f'"{value}"'
        elif isinstance(value, list):
            return '[' + ', '.join(handle_value(item) for item in value) + ']'
        return str(value)

    def convert_dict_to_json(d):
        json_parts = []
        for key, value in d.items():
            json_parts.append(f'"{key}": {handle_value(value)}')
        return '{' + ', '.join(json_parts) + '}'

    return '[' + ', '.join(convert_dict_to_json(student) for student in data) + ']'

def flatten_query_params(query_params):
    """
    Flattens a dictionary of query parameters by appending the index of each value in hexadecimal format to the key.

    :param query_params: A dictionary where keys are parameter names and values are lists of parameter values.
    :return: A new dictionary with keys in the format 'key[index]' and values from the original lists.
    """
    flattened_dict = {}
    for key, values in query_params.items():
        for i, value in enumerate(values):
            hex_index = format(i, 'x')
            new_key = f"{key}[{hex_index}]"
            flattened_dict[new_key] = value
    return flattened_dict

def chain_functions(func_1, func_2, unpack):
    """
    Chains two functions together with an optional unpacking step.

    Parameters:
    - func_1: A callable function whose result will be passed to func_2.
    - func_2: A callable function that receives the result of func_1.
    - unpack: A boolean flag indicating whether to unpack the result of func_1 if it is a tuple or list.

    Returns:
    - The result of func_2 if no exceptions occur, otherwise None.
    """
    try:
        result = func_1()
        if unpack and isinstance(result, (tuple, list)):
            return func_2(*result)
        else:
            return func_2(result)
    except:
        return None

def skip_multiply(n):
    """
    Recursively computes the product of every second integer starting from n down to 1 if n is odd,
    or down to 2 if n is even.

    :param n: The starting integer from which to compute the product.
    :return: The computed product as an integer.
    """
    # Base case for odd n
    if n == 1:
        return 1
    # Base case for even n
    elif n == 2:
        return 2
    # Recursive case
    else:
        return n * skip_multiply(n - 2)

def has_matching_head_word(sentence, entities):
    """
    Determines if any head word from the list of entities is present in the given sentence.

    :param sentence: List of strings representing the words in a sentence.
    :param entities: List of tuples, where each tuple contains a string (entity name) and a string (head word).
    :return: Boolean value indicating if any head word is present in the sentence.
    """
    head_words = {entity[1] for entity in entities}
    return any(word in head_words for word in sentence)

def validate_ip(ip):
    """
    Validates if the given string is a valid IPv4 address.

    Parameters:
    ip (str): The IP address to validate.

    Returns:
    bool: True if the IP address is valid, False otherwise.
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
        if part != str(num):
            return False
    return True

def longest_common_prefix(words):
    """
    Finds the longest common prefix string amongst the given list of strings.

    :param words: List of strings
    :return: Longest common prefix string or an empty string if no common prefix exists
    """
    if not words:
        return ""

    shortest_word = min(words, key=len)

    for i, char in enumerate(shortest_word):
        for word in words:
            if word[i] != char:
                return shortest_word[:i]

    return shortest_word

def sum_of_primes_below(n):
    """
    Calculate the sum of all prime numbers below a given number n using the Sieve of Eratosthenes algorithm.

    Parameters:
    n (int): The upper limit (exclusive) for finding prime numbers.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    prime = [True] * n
    p = 2
    while p * p < n:
        if prime[p]:
            for i in range(p * p, n, p):
                prime[i] = False
        p += 1

    return sum(p for p in range(2, n) if prime[p])

def find_first_non_empty_string(strings):
    """
    Recursively finds the first non-empty string in a list of strings.

    Parameters:
    strings (list of str): The list of strings to search through.

    Returns:
    str: The first non-empty string, or an empty string if none exists.
    """
    if not strings:
        return ""
    if strings[0]:
        return strings[0]
    return find_first_non_empty_string(strings[1:])

def find_longest_common_subsequence(str1, str2):
    """
    Returns the longest common subsequence of two input strings.

    :param str1: First input string
    :param str2: Second input string
    :return: Longest common subsequence as a string
    """
    # Create a 2D array to store lengths of longest common subsequence.
    dp = [[0] * (len(str2) + 1) for _ in range(len(str1) + 1)]

    # Build the dp array from bottom up
    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the longest common subsequence from the dp array
    lcs = []
    i, j = len(str1), len(str2)
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            lcs.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # The lcs list contains the LCS in reverse order
    lcs.reverse()
    return ''.join(lcs)

