def find_max_and_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values in the list.
    If the list is empty, returns (None, None).

    :param numbers: List of integers
    :return: Tuple (max_value, min_value) or (None, None) if the list is empty
    """
    if not numbers:
        return (None, None)
    else:
        return (max(numbers), min(numbers))

def remove_duplicates_and_sort(arr):
    """
    Removes duplicates from the list and sorts it using Bubble Sort algorithm.

    Parameters:
    arr (list): A list of integers.

    Returns:
    list: A sorted list of integers with duplicates removed.
    """
    # Step 1: Remove duplicates
    unique = []
    for num in arr:
        if num not in unique:
            unique.append(num)

    # Step 2: Sort the unique list using Bubble Sort
    n = len(unique)
    for i in range(n):
        for j in range(0, n-i-1):
            if unique[j] > unique[j+1]:
                unique[j], unique[j+1] = unique[j+1], unique[j]

    return unique

def find_longest_sorted_sublist(items):
    """
    Returns the longest contiguous sublist within the given list `items` that is sorted in non-decreasing order.
    If there are multiple sublists of the same maximum length, the first one encountered is returned.

    :param items: List of integers and floating-point numbers.
    :return: List representing the longest sorted sublist.
    """
    if not items:
        return []

    longest_sorted = [items[0]]
    current_sorted = [items[0]]

    for i in range(1, len(items)):
        if items[i] >= items[i - 1]:
            current_sorted.append(items[i])
        else:
            if len(current_sorted) > len(longest_sorted):
                longest_sorted = current_sorted
            current_sorted = [items[i]]

    if len(current_sorted) > len(longest_sorted):
        longest_sorted = current_sorted

    return longest_sorted

def parse_log(log_file):
    """
    Parses a log file string and returns a dictionary with the count of each log level (INFO, WARNING, ERROR).

    :param log_file: A string representing the log file.
    :return: A dictionary with log levels as keys and their counts as values.
    """
    import re

    log_count = {}
    log_level_pattern = re.compile(r'^\[(INFO|WARNING|ERROR)\]: .+')
    log_lines = log_file.splitlines()

    for line in log_lines:
        match = log_level_pattern.match(line)
        if match:
            log_level = match.group(1)
            if log_level in log_count:
                log_count[log_level] += 1
            else:
                log_count[log_level] = 1

    return log_count

def find_lis_length(nums):
    """
    Finds the length of the longest increasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize dp array with 1

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def count_slang_phrases(phrase_list, slang_words):
    """
    Counts the number of phrases containing at least one slang word, with each slang word
    appearing no more than twice in any given phrase.

    :param phrase_list: List of strings, where each string is a phrase.
    :param slang_words: Set of strings representing slang words.
    :return: Integer representing the number of valid phrases.
    """
    def is_valid_phrase(phrase, slang_words):
        """
        Checks if a phrase contains at least one slang word with each slang word appearing
        no more than twice.

        :param phrase: String representing a phrase.
        :param slang_words: Set of strings representing slang words.
        :return: Boolean indicating if the phrase is valid.
        """
        words = phrase.split()
        slang_count = {word: 0 for word in slang_words if word in words}
        for word in words:
            if word in slang_count:
                slang_count[word] += 1
                if slang_count[word] > 2:
                    return False
        return bool(slang_count)

    return sum(is_valid_phrase(phrase, slang_words) for phrase in phrase_list)

def classify_file_paths(file_paths):
    """
    Classifies each file path into one of the categories: 'Code', 'Documentation', 'Data', or 'Other'.

    Args:
    file_paths (list of str): A list of file paths.

    Returns:
    list of tuples: A list where each tuple contains a file path and its category.
    """
    code_extensions = {'.py', '.java', '.cpp', '.c', '.js', '.html', '.css', '.go', '.sql'}
    doc_extensions = {'.txt', '.md', '.docx', '.pdf', '.rst'}
    data_extensions = {'.csv', '.json', '.xml', '.yaml', '.xls', '.xlsx', '.db', '.sqlite', '.log'}

    classifications = []

    for path in file_paths:
        if '.' in path:
            _, ext = path.rsplit('.', 1)
            ext = '.' + ext.lower()
        else:
            ext = ''

        if ext in code_extensions:
            category = 'Code'
        elif ext in doc_extensions:
            category = 'Documentation'
        elif ext in data_extensions:
            category = 'Data'
        else:
            category = 'Other'

        classifications.append((path, category))

    return classifications

def flatten_structure(nested):
    """Helper function to flatten a list or tuple."""
    for item in nested:
        if isinstance(item, (list, tuple)):
            yield from flatten_structure(item)
        else:
            yield item

def calculate_sum(num1, num2=100):
    """
    Function to calculate the sum of two numbers or lists/tuples of numbers.
    Handles conversion of floats to integers and raises TypeError for invalid inputs.
    """
    def process_number(num):
        """Helper function to process each number according to the rules."""
        if isinstance(num, float):
            return int(num)
        elif not isinstance(num, int):
            raise TypeError(f"Expected integer or float, got {type(num).__name__}")
        return num

    # Flatten num1 and num2 if they are lists or tuples
    flat_num1 = list(flatten_structure(num1)) if isinstance(num1, (list, tuple)) else [num1]
    flat_num2 = list(flatten_structure(num2)) if isinstance(num2, (list, tuple)) else [num2]

    # Validate and process each number
    processed_numbers = [process_number(num) for num in flat_num1 + flat_num2]

    # Calculate and return the sum
    return sum(processed_numbers)

def remove_frames(f, *args, **kwds):
    """
    Simulates the removal of specific frames from the call stack by wrapping the function call.

    Parameters:
    f (callable): The function to be called.
    *args: Positional arguments to be passed to the function.
    **kwds: Keyword arguments to be passed to the function.

    Returns:
    The result of calling the function `f` with the provided arguments.
    """
    def wrapper():
        return f(*args, **kwds)
    return wrapper()

def comb_to_str(combinations):
    """
    Converts a list of combinations, where each combination is a tuple that may contain integers
    and other nested tuples, into a string. Each combination is represented as a substring with
    integers separated by commas, and substrings are separated by semicolons. Nested tuples are
    recursively expanded.

    :param combinations: List of tuples representing combinations
    :return: String representation of the combinations
    """
    def flatten_tuple(t):
        for item in t:
            if isinstance(item, tuple):
                yield from flatten_tuple(item)
            else:
                yield item

    def tuple_to_str(t):
        return ','.join(map(str, flatten_tuple(t)))

    return ';'.join(tuple_to_str(comb) for comb in combinations)

def longest_increasing_subsequence_length(nums):
    """
    Returns the length of the longest strictly increasing subsequence in the list of integers nums.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest strictly increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize the dp array with 1s

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

