def find_longest_palindrome_substring(s: str) -> str:
    """
    Finds the longest palindromic substring in the given string s.

    :param s: Input string
    :return: Longest palindromic substring
    """
    n = len(s)
    if n == 0:
        return ""

    dp = [[False] * n for _ in range(n)]
    start = 0
    max_length = 1

    for i in range(n):
        dp[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1
            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True
                if k > max_length:
                    start = i
                    max_length = k

    return s[start:start + max_length]

from collections import Counter
from statistics import mean, median, mode, StatisticsError

def calculate(calculation, numbers):
    """
    Perform the specified calculation on a list of numbers.

    Parameters:
    calculation (str): The type of calculation to perform ('mean', 'median', 'mode', 'min', 'max', 'range').
    numbers (list): A list of integers and/or floating-point numbers.

    Returns:
    float or int or None: The result of the calculation, or None if the list is empty.

    Raises:
    ValueError: If the calculation type is not recognized.
    """
    if not numbers:
        return None

    try:
        if calculation == 'mean':
            result = mean(numbers)
        elif calculation == 'median':
            result = median(numbers)
        elif calculation == 'mode':
            result = mode(numbers)
        elif calculation == 'min':
            result = min(numbers)
        elif calculation == 'max':
            result = max(numbers)
        elif calculation == 'range':
            result = max(numbers) - min(numbers)
        else:
            raise ValueError("Invalid calculation type provided.")
    except (StatisticsError, ValueError) as e:
        raise ValueError(str(e))

    return result

def escapeXML(sText):
    """
    Replaces XML special characters in the input string with their corresponding XML entities.

    :param sText: The input string containing potential XML special characters.
    :return: A new string with XML special characters replaced by their entities.
    """
    escaped_text = ""
    for char in sText:
        if char == '&':
            escaped_text += '&amp;'
        elif char == '<':
            escaped_text += '&lt;'
        elif char == '>':
            escaped_text += '&gt;'
        elif char == '"':
            escaped_text += '&quot;'
        else:
            escaped_text += char
    return escaped_text

def bin_labeler(bins, element):
    """
    Determine which bin the given element belongs to, based on the specified bin boundaries.

    :param bins: List of integers representing the boundaries of sorted bins.
    :param element: Integer element to be labeled.
    :return: String indicating the bin label or that the element does not belong to any bin.
    """
    for i in range(len(bins) - 1):
        if bins[i] <= element < bins[i + 1]:
            return f"Bin {i + 1} ({bins[i]} <= x < {bins[i + 1]})"

    if element < bins[0]:
        return f"Element {element} is less than the lower limit of the first bin"

    if element >= bins[-1]:
        return f"Element {element} is greater than or equal to the upper limit of the last bin"

    return "Element does not belong to any bin"

def optimize_string(s: str) -> str:
    """
    Processes the input string by removing consecutive duplicate characters,
    ensuring each character appears only once while maintaining the original order.

    :param s: The input string consisting of lowercase English letters.
    :return: The optimized string with consecutive duplicates removed.
    """
    if not s:
        return ""
    optimized_str = [s[0]]
    for char in s[1:]:
        if char != optimized_str[-1]:
            optimized_str.append(char)
    return ''.join(optimized_str)

