def calculate_recall(actual, predicted):
    """
    Calculate the recall for a binary classification problem, ignoring uncertain classifications (denoted by 2).

    Parameters:
    actual (list of int): List of actual classifications (0, 1, or 2).
    predicted (list of int): List of predicted classifications (0, 1, or 2).

    Returns:
    float: The recall value, or 0 if TP + FN is zero.
    """
    TP = 0  # True Positives
    FN = 0  # False Negatives

    for i in range(len(actual)):
        if actual[i] == 1 and predicted[i] == 1:
            TP += 1
        elif actual[i] == 1 and predicted[i] != 1:
            FN += 1

    # Calculate recall
    if TP + FN == 0:
        return 0
    else:
        return TP / (TP + FN)

def find_unique_elements(dict1, dict2):
    """
    Returns a new nested dictionary containing only the key-value pairs from dict1
    where the keys are not present in any level of dict2. If a key is present in both
    dictionaries and the corresponding values are different integers, the key-value
    pair from dict1 is included in the result.

    :param dict1: The first nested dictionary.
    :param dict2: The second nested dictionary.
    :return: A nested dictionary with unique elements from dict1.
    """
    def recursive_diff(d1, d2):
        result = {}
        for key, value in d1.items():
            if key not in d2 or isinstance(value, int) and value != d2[key]:
                result[key] = value
            elif isinstance(value, dict):
                child_diff = recursive_diff(value, d2.get(key, {}))
                if child_diff:
                    result[key] = child_diff
        return result

    return recursive_diff(dict1, dict2)

def days_in_month(year, month):
    """
    Returns the number of days in the specified month of the given year.
    Handles leap years correctly and returns -1 for invalid inputs.

    Parameters:
    year (int): The year (1-9999).
    month (int): The month (1-12).

    Returns:
    int: Number of days in the month, or -1 if the input is invalid.
    """
    if year < 1 or year > 9999:
        return -1
    if month < 1 or month > 12:
        return -1

    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                month_days[1] = 29
        else:
            month_days[1] = 29

    return month_days[month - 1]

def search_rotated_matrix(matrix, target):
    """
    Searches for a target value in a 2D grid that has been rotated 90 degrees clockwise.

    :param matrix: List[List[int]] - The rotated 2D grid.
    :param target: int - The target value to search for.
    :return: bool - True if the target is found, False otherwise.
    """
    if not matrix or not matrix[0]:
        return False

    N = len(matrix)  # Number of rows in the original matrix
    M = len(matrix[0])  # Number of columns in the original matrix

    for i in range(M):
        left, right = 0, N - 1
        while left <= right:
            mid = (left + right) // 2
            value = matrix[mid][M - 1 - i]

            if value == target:
                return True
            elif value < target:
                left = mid + 1
            else:
                right = mid - 1

    return False

def convert_to_html(markdown_text):
    """
    Convert a markdown document to an HTML document by transforming basic markdown syntax to HTML tags.

    :param markdown_text: A string representing the markdown document.
    :return: A string representing the HTML document.
    """
    lines = markdown_text.split('\n')
    html_text = []

    for line in lines:
        if line.startswith('#'):
            level = len(line) - len(line.lstrip('#'))
            header_text = line.strip('#').strip()
            html_text.append(f"<h{level}>{header_text}</h{level}>")
        else:
            bold_start = line.find('**')
            while bold_start != -1:
                bold_end = line.find('**', bold_start + 2)
                if bold_end != -1:
                    line = (line[:bold_start] + f"<strong>{line[bold_start + 2:bold_end]}</strong>" +
                            line[bold_end + 2:])
                bold_start = line.find('**', bold_start + 8)

            italic_start = line.find('*')
            while italic_start != -1:
                italic_end = line.find('*', italic_start + 1)
                if italic_end != -1 and line[italic_start + 1] != '*':
                    line = (line[:italic_start] + f"<em>{line[italic_start + 1:italic_end]}</em>" +
                            line[italic_end + 1:])
                italic_start = line.find('*', italic_start + 5)

            if line.strip():
                html_text.append(f"<p>{line}</p>")

    return '\n'.join(html_text)

import math

def find_closest_pair(points):
    """
    Finds and returns a tuple containing the two points with the smallest Euclidean distance.

    :param points: List of tuples, where each tuple contains the x and y coordinates of a point.
    :return: Tuple containing the two points with the smallest Euclidean distance.
    """
    if len(points) < 2:
        raise ValueError("At least two points are required")

    def euclidean_distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    min_distance = float('inf')
    closest_pair = None

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            distance = euclidean_distance(points[i], points[j])
            if distance < min_distance:
                min_distance = distance
                closest_pair = (points[i], points[j])

    return closest_pair

def compute_factorial(n):
    """
    Computes the factorial of a given non-negative integer n using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the given integer n.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * compute_factorial(n - 1)

