def generate_prime_sieve(limit):
    """
    Generate a list of prime numbers up to a given limit using the Sieve of Eratosthenes algorithm.

    :param limit: An integer representing the upper bound for generating prime numbers.
    :return: A list of prime numbers less than or equal to the given limit.
    """
    if limit < 2:
        return []

    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False

    for num in range(2, int(limit**0.5) + 1):
        if sieve[num]:
            for multiple in range(num*num, limit + 1, num):
                sieve[multiple] = False

    return [num for num, is_prime in enumerate(sieve) if is_prime]

def validateParentheses(s):
    """
    Determines if the input string has valid parentheses.

    Args:
    s (str): A string consisting of '(' and ')' characters.

    Returns:
    bool: True if the string has valid parentheses, False otherwise.
    """
    stack = []
    matching_parentheses = {')': '('}

    for char in s:
        if char in matching_parentheses:
            if not stack or stack[-1] != matching_parentheses[char]:
                return False
            stack.pop()
        else:
            stack.append(char)

    return not stack

def countPrimes(n):
    """
    Returns the count of prime numbers less than n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit (exclusive) for counting prime numbers.
    :return: An integer count of prime numbers less than n.
    """
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for start in range(2, int(n ** 0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n, start):
                sieve[multiple] = False

    return sum(sieve)

def update_key_counter(idx, key, same, opposite):
    """
    Updates the dictionaries `same` and `opposite` based on the given `idx` and `key`.

    Parameters:
    idx (int): The index to be added or removed.
    key (tuple): The key in the dictionaries.
    same (dict): Dictionary where keys are tuples and values are lists of indices.
    opposite (dict): Dictionary where keys are tuples and values are lists of indices.

    Returns:
    tuple or None: The key if not None, otherwise None.
    """
    if key is None:
        return None

    if key in opposite:
        if idx in opposite[key]:
            opposite[key].remove(idx)
        if not opposite[key]:
            del opposite[key]

    if key in same:
        if idx in same[key]:
            same[key].remove(idx)
        if not same[key]:
            del same[key]
    else:
        same[key] = [idx]

    return key

def check_parentheses_balance(expression):
    """
    Check if the parentheses in the given expression are balanced.

    :param expression: A string containing the expression to be checked.
    :return: True if the parentheses are balanced, False otherwise.
    """
    open_count = 0
    for char in expression:
        if char == '(':
            open_count += 1
        elif char == ')':
            open_count -= 1
            if open_count < 0:
                return False
    return open_count == 0

