def optimize_fibonacci(n, memo=None):
    """
    Computes the nth Fibonacci number using memoization to optimize performance.

    :param n: An integer representing the position in the Fibonacci sequence.
    :param memo: A dictionary used to store previously computed Fibonacci numbers.
    :return: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 2:
        return 1
    memo[n] = optimize_fibonacci(n - 1, memo) + optimize_fibonacci(n - 2, memo)
    return memo[n]

def find_in_nested_dict(d, value):
    """
    Recursively checks if a given value exists within a nested dictionary.

    Parameters:
    d (dict): The nested dictionary to search within.
    value: The target value to find.

    Returns:
    bool: True if the value is found, False otherwise.
    """
    if isinstance(d, dict):
        return find_in_nested_dict(list(d.keys()), value) or find_in_nested_dict(list(d.values()), value)
    elif isinstance(d, list):
        if not d:
            return False
        head, *tail = d
        return find_in_nested_dict(head, value) or find_in_nested_dict(tail, value)
    else:
        return d == value

