def is_prime_number(n):
    """
    Determines if the given integer n is a prime number.

    :param n: int, the number to be checked for primality
    :return: bool, True if n is prime, False otherwise
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

def get_unique_uppercase_nodes(connections):
