def calculate_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List of integers representing stock prices.
    :return: Maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        else:
            profit = price - min_price
            if profit > max_profit:
                max_profit = profit

    return max_profit

def encrypt_message(message, shift):
    """
    Encrypts a given message using a Caesar cipher with a specified shift value.

    Parameters:
    message (str): The string to be encrypted.
    shift (int): The number of positions to shift each letter.

    Returns:
    str: The encrypted message.
    """
    encrypted_message = []

    for char in message:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')
            encrypted_char = chr(start + (ord(char) - start + shift_amount) % 26)
            encrypted_message.append(encrypted_char)
        else:
            encrypted_message.append(char)

    return ''.join(encrypted_message)

