def is_prime_number(n: int) -> bool:
    """
    Determines if the given integer n is a prime number.

    Args:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    factors_up_to = int(n ** 0.5) + 1
    for i in range(3, factors_up_to, 2):
        if n % i == 0:
            return False
    return True

