def reverse_dict(input_dict):
    """
    Reverses the given dictionary by swapping keys with their corresponding values.
    If multiple keys have the same value, they are stored in a list.

    :param input_dict: Dictionary with hashable keys and values.
    :return: Dictionary with values as keys and lists of original keys as values.
    """
    reversed_dict = {}
    for key, value in input_dict.items():
        if value in reversed_dict:
            reversed_dict[value].append(key)
        else:
            reversed_dict[value] = [key]
    return reversed_dict

def get_season_name(monthcode, region='US'):
    """
    Determines the season for a given month and region.

    Parameters:
    - monthcode (int): An integer representing the month (1 for January, 2 for February, etc.).
    - region (str): A string representing the region ('US', 'Australia', 'India').

    Returns:
    - str: A string representing the season or an error message if the input is invalid.
    """
    # Define seasonal divisions for different regions
    seasons = {
        'US': {
            (1, 2, 12): 'Winter',
            (3, 4, 5): 'Spring',
            (6, 7, 8): 'Summer',
            (9, 10, 11): 'Autumn'
        },
