            (3, 4, 5): 'Autumn',
            (6, 7, 8): 'Winter',
            (9, 10, 11): 'Spring'
        },
        'India': {
            (12, 1, 2): 'Winter',
            (3, 4, 5): 'Summer',
            (6, 7, 8): 'Monsoon',
            (9, 10, 11): 'Autumn'
        }
    }

    # Validate monthcode input
