def sum_values(data):
    """
    Computes the sum of all values in a dictionary, including those in nested dictionaries.

    :param data: A dictionary with integer values or nested dictionaries.
    :return: The sum of all integer values in the dictionary.
    """
    total_sum = 0
    for value in data.values():
        if isinstance(value, dict):
            total_sum += sum_values(value)
        else:
            total_sum += value
    return total_sum

def normalize_input(input_data, default_value):
    """
    Normalize the input data by returning a flattened list of values.

    Parameters:
    input_data: The input data to be normalized.
    default_value: The default value to use if input_data is None.

    Returns:
    A list containing the normalized input data.
    """
    def flatten(lst):
        """
        Helper function to flatten nested lists.

        Parameters:
        lst: The list to be flattened.

        Returns:
        A flattened list.
        """
        flat_list = []
        for item in lst:
            if isinstance(item, list):
                flat_list.extend(flatten(item))
            else:
                flat_list.append(item)
        return flat_list

    if input_data is None:
        return [default_value]
    elif isinstance(input_data, list):
        return flatten(input_data)
    else:
        return [input_data]

from typing import List

def find_smallest_missing_positive(nums: List[int]) -> int:
    """
    Finds the smallest missing positive integer in the list.

    :param nums: List of integers which may contain duplicates and negative numbers.
    :return: The smallest missing positive integer.
    """
    n = len(nums)

    # Step 1: Segregate positive numbers from non-positive numbers.
    j = 0
    for i in range(n):
        if nums[i] <= 0:
            nums[i], nums[j] = nums[j], nums[i]
            j += 1

    # Step 2: Use the index as a hash to record the presence of numbers.
    for i in range(j, n):
        val = abs(nums[i])
        if j <= val <= n - j:
            if nums[val - 1 + j] > 0:
                nums[val - 1 + j] = -nums[val - 1 + j]

    # Step 3: Find the first index where the value is positive.
    for i in range(j, n):
        if nums[i] > 0:
            return i - j + 1

    return n - j + 1

def validate_weather_data(weather_data):
    """
    Validates the weather_data list to ensure it meets specific criteria:
    - Is a list.
    - Contains exactly three elements.
    - The first element is a float with one decimal place.
    - The second element is a float with two decimal places.
    - The third element is a valid weather condition from the set {"sunny", "cloudy", "rainy"}.

    Parameters:
    weather_data (list): The list containing weather data.

    Returns:
    str: A detailed validation report.
    """
    valid_conditions = {"sunny", "cloudy", "rainy"}
    validation_report = []

    if isinstance(weather_data, list):
        validation_report.append("The weather_data is a list.")
    else:
        validation_report.append("The weather_data is not a list.")
        return "\n".join(validation_report)

    if len(weather_data) == 3:
        validation_report.append("The weather_data has the correct length (3 elements).")
    else:
        validation_report.append("The weather_data does not have the correct length (not 3 elements).")
        return "\n".join(validation_report)

    if isinstance(weather_data[0], float) and weather_data[0] == round(weather_data[0], 1):
        validation_report.append("The first element is a float with exactly one decimal place.")
    else:
        validation_report.append("The first element is not a float with exactly one decimal place.")

    if isinstance(weather_data[1], float) and weather_data[1] == round(weather_data[1], 2):
        validation_report.append("The second element is a float with exactly two decimal places.")
    else:
        validation_report.append("The second element is not a float with exactly two decimal places.")

    if isinstance(weather_data[2], str) and weather_data[2] in valid_conditions:
        validation_report.append("The third element is a valid weather condition.")
    else:
        validation_report.append("The third element is not a valid weather condition.")

    return "\n".join(validation_report)

def compute_factorial(n: int) -> int:
    """
    Compute the factorial of a given non-negative integer using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the given integer n. If n is 0 or 1, the function returns 1.

    Raises:
    ValueError: If the input is a negative integer.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0 or n == 1:
        return 1
    else:
        return n * compute_factorial(n - 1)

def find_common_subsequence(list1, list2):
    """
    Returns the longest common subsequence between two lists of integers.

    :param list1: List of integers.
    :param list2: List of integers.
    :return: List of integers representing the longest common subsequence.
    """
    m, n = len(list1), len(list2)

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if list1[i - 1] == list2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if list1[i - 1] == list2[j - 1]:
            lcs.append(list1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    lcs.reverse()

    return lcs

def compare_rules(r1, r2):
    """
    Compare two association rules based on their precedence.

    Parameters:
    r1 (dict): The first rule to compare.
    r2 (dict): The second rule to compare.

    Returns:
    int: 1 if r1 has higher precedence, -1 if r2 has higher precedence, 0 if they have the same precedence.
    """
    # Check if one rule is None and the other is not
    if r1 is None and r2 is not None:
        return -1
    if r1 is not None and r2 is None:
        return 1
    if r1 is None and r2 is None:
        return 0

    # Compare based on confidence
    if r2['confidence'] > r1['confidence']:
        return -1
    if r2['confidence'] < r1['confidence']:
        return 1

    # Compare based on support
    if r2['support'] > r1['support']:
        return -1
    if r2['support'] < r1['support']:
        return 1

    # Compare based on number of conditions
    if len(r1['condset']) < len(r2['condset']):
        return 1
    if len(r1['condset']) > len(r2['condset']):
        return -1

    # Compare based on specificity
    if r2['specificity'] > r1['specificity']:
        return -1
    if r2['specificity'] < r1['specificity']:
        return 1

    # If all conditions are the same
    return 0

def find_most_common_character(s):
    """
    Returns the most frequently occurring non-whitespace character in the string.
    If there are ties, returns the character that appears first in the string.

    :param s: Input string
    :return: Most common non-whitespace character
    """
    frequency_dict = {}

    for char in s:
        if char.isspace():
            continue
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1

    max_char = None
    max_frequency = 0

    for char in s:
        if char.isspace():
            continue
        if frequency_dict[char] > max_frequency:
            max_char = char
            max_frequency = frequency_dict[char]

    return max_char

