def calculate_grades(grades):
    """
    Convert a list of numerical grades to letter grades based on a fixed grading scale.

    Parameters:
    grades (list of int): A list of integers representing student grades.

    Returns:
    list of str: A list of strings representing the corresponding letter grades.
    """
    letter_grades = []
    for grade in grades:
        if grade >= 90:
            letter_grades.append('A')
        elif grade >= 80:
            letter_grades.append('B')
        elif grade >= 70:
            letter_grades.append('C')
        elif grade >= 60:
            letter_grades.append('D')
