def swap_keys_values(input_dict):
    """
    Swaps the keys and values of the input dictionary. If a value appears more than once,
    the corresponding key in the new dictionary is a list of all keys that had that value.

    :param input_dict: Dictionary with unique keys.
    :return: Dictionary with keys and values swapped.
    """
    swapped_dict = {}
    for key, value in input_dict.items():
        if value in swapped_dict:
            if not isinstance(swapped_dict[value], list):
                swapped_dict[value] = [swapped_dict[value]]
            swapped_dict[value].append(key)
        else:
            swapped_dict[value] = key
    return swapped_dict

def sum_of_digits_recursive(number: int) -> int:
    """
    Recursively calculates the sum of the digits of a non-negative integer.

    :param number: A non-negative integer whose digits are to be summed.
    :return: The sum of the digits of the given number.
    """
    if number == 0:
        return 0
    return number % 10 + sum_of_digits_recursive(number // 10)

