def html_escape(input_string):
    """
    Replaces HTML special characters in the input string with their corresponding HTML entities.

    Parameters:
    input_string (str): The string to be processed.

    Returns:
    str: A new string with HTML special characters replaced.
    """
    escaped_string = ""
    for char in input_string:
        if char == '&':
            escaped_string += '&amp;'
        elif char == '<':
            escaped_string += '&lt;'
        elif char == '>':
            escaped_string += '&gt;'
        elif char == '"':
            escaped_string += '&quot;'
        elif char == "'":
            escaped_string += '&apos;'
        else:
            escaped_string += char
    return escaped_string

def filter_prime_numbers(n):
    """
    Returns a list of all prime numbers less than n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit (exclusive) for prime number generation.
    :return: A list of integers representing all prime numbers less than n.
    """
    if n <= 2:
        return []

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

