def validate_ol(table):
    """
    Validates if the given table represents a valid ordered list based on specific criteria.

    Parameters:
    table (list of lists): The table to be validated.

    Returns:
    bool: True if the table is a valid ordered list, False otherwise.
    """
    for i in range(len(table)):
        if len(table[i]) != 2:
            return False

        s, inner_list = table[i]

        if inner_list != []:
            return False

        if not (1 <= len(s) <= 3):
            return False

        if s[-1] not in {'.', ')'}:
            return False

        if not s[:-1].isalnum():
            return False

        if i > 0 and set(s[:-1]).intersection(set(table[i-1][0][:-1])):
            return False

    return True

def count_odds_evens(numbers):
