def create_enum(**kwargs):
    """
    Creates a new enumeration type with the provided keyword arguments as attributes.

    Args:
        **kwargs: Arbitrary keyword arguments where each keyword is an enumeration name
                  and each value is the corresponding enumeration value.

    Returns:
        A new type with the provided enumeration values as attributes and a method `values()`
        that returns the enumeration values in the order they were provided.
    """
    class Enum:
        def __init__(self):
            raise AttributeError("Cannot create new instance of Enum")

        def __setattr__(self, key, value):
            raise AttributeError("Cannot set attributes of Enum")

        def __delattr__(self, item):
            raise AttributeError("Cannot delete attributes of Enum")

        @staticmethod
        def values():
            return list(kwargs.values())

    for key, value in kwargs.items():
        setattr(Enum, key, value)

    return Enum

def find_longest_string(strings):
    """
    Finds and returns the longest string in a list. In case of a tie, returns the first longest string encountered.

    :param strings: List of non-empty strings.
    :return: The longest string in the list.
    """
    if not strings:
        return None
    longest = strings[0]
    for string in strings:
        if len(string) > len(longest):
            longest = string
    return longest

def flatten(lst):
