def merge_and_remove_duplicates(list1: list, list2: list) -> list:
    """Merges two lists, flattens them, and removes duplicate elements."""
    # Flatten both lists
    flat_list1 = list(flatten(list1))
    flat_list2 = list(flatten(list2))

    # Merge and remove duplicates using a set
    merged_set = set(flat_list1) | set(flat_list2)

    # Convert set back to list
    return list(merged_set)

def count_primes(n):
    """
    Returns the count of prime numbers between 1 and n (inclusive).

    :param n: An integer representing the upper limit of the range.
    :return: An integer representing the count of prime numbers in the range.
    """
    if n < 2:
        return 0

    prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if prime[p]:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1

    return sum(prime[2:])

def gcd(a, b):
    """
    Calculate the greatest common divisor (GCD) of two integers using the Euclidean algorithm.

    Parameters:
    a (int): First integer
    b (int): Second integer

    Returns:
    int: The greatest common divisor of a and b
    """
    # Handle cases where a or b is zero
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Ensure a and b are positive
    a, b = abs(a), abs(b)

    # Use the Euclidean algorithm to find the GCD
    while b != 0:
        a, b = b, a % b
    return a

def get_instance(method):
    """
    Returns the instance of the class to which the method is bound, or None if the method is not bound to an instance.

    :param method: A method object.
    :return: The instance of the class or None.
    """
    try:
        return method.__self__
    except AttributeError:
        return None

def find_unique_elements(list1, list2):
    """
    Returns a list of unique elements from both input lists, sorted by their first appearance index.

    :param list1: List of unique integers.
    :param list2: List of unique integers.
    :return: Sorted list of unique integers.
    """
    first_appearance_index = {}

    for index, num in enumerate(list1):
        if num not in first_appearance_index:
            first_appearance_index[num] = index + 1

    for index, num in enumerate(list2):
        if num not in first_appearance_index:
            first_appearance_index[num] = index + len(list1) + 1

    unique_elements_sorted = sorted(first_appearance_index.keys(), key=lambda x: first_appearance_index[x])

    return unique_elements_sorted

def UniqueElements(lst):
    """
    Processes a list of integers and returns a dictionary containing only those integers
    that appear an odd number of times, with the integers as keys and their counts as values.

    :param lst: List of integers
    :return: Dictionary with integers as keys and their counts as values for integers appearing an odd number of times
    """
    element_counts = {}
    for num in lst:
        if num in element_counts:
            element_counts[num] += 1
        else:
            element_counts[num] = 1

    return {key: value for key, value in element_counts.items() if value % 2 != 0}

