    - protocol (str, optional): The protocol for transferring hypertext, defaulting to 'http'.

    Returns:
    - str: The constructed URL.
    """
    if port is not None:
        try:
            int(port)
        except ValueError:
            port = None

    if port is not None:
        return f"{protocol}://{server}:{port}"
    else:
        return f"{protocol}://{server}"

def is_prime_optimized(num):
    """Return True if num is a prime number, otherwise False."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_tax(income):
    """
    Calculate the tax based on the given income using progressive tax brackets.

    Parameters:
    income (float): The income for which the tax needs to be calculated.

    Returns:
    float: The total tax amount.
    """
    if income <= 0:
        return 0.0
    elif income <= 10000:
        return income * 0.10
    elif income <= 20000:
        return 10000 * 0.10 + (income - 10000) * 0.20
    elif income <= 50000:
        return 10000 * 0.10 + 10000 * 0.20 + (income - 20000) * 0.30
    else:
        return 10000 * 0.10 + 10000 * 0.20 + 30000 * 0.30 + (income - 50000) * 0.40

def find_max_in_2d_array(array):
