    :param array: List[List[int]] - A 2D list of integers.
    :return: int - The maximum integer value in the 2D list.
    """
    max_value = float('-inf')  # Start with the smallest possible value
    for row in array:
        for element in row:
            if element > max_value:
                max_value = element
    return max_value

