def remove_prefix(s, p):
    """
    Removes the prefix p from the string s if s starts with p.
    Returns s unchanged if it does not start with p.

    :param s: The original string
    :param p: The prefix to be removed
    :return: The modified string after removing the prefix if it exists
    """
    prefix_length = len(p)
    string_length = len(s)

    if prefix_length > string_length:
        return s

    for i in range(prefix_length):
        if p[i] != s[i]:
            return s

    result = []
    for i in range(prefix_length, string_length):
        result.append(s[i])

    return ''.join(result)

def find_maximum_value(tree):
    """
    Returns the maximum value in a binary tree represented as a list of dictionaries.

    :param tree: List of dictionaries, where each dictionary represents a node in the binary tree.
    :return: Integer, the maximum value found in the binary tree.
    """
    if not tree:
        return None

    max_value = float('-inf')
    nodes_to_visit = [0]

    while nodes_to_visit:
        current_index = nodes_to_visit.pop(0)
        node = tree[current_index]

        if node['value'] > max_value:
            max_value = node['value']

        if node['left'] is not None:
            nodes_to_visit.append(node['left'])

        if node['right'] is not None:
            nodes_to_visit.append(node['right'])

    return max_value

def flatten(nested_list):
    """
    Flattens a nested list of integers into a single list of integers.

    :param nested_list: List of integers or nested lists of integers
    :return: Flattened list of integers
    """
    result = []

    for element in nested_list:
        if isinstance(element, list):
            result.extend(flatten(element))
        else:
            result.append(element)

    return result

def FibonacciSum(n):
    """
    Calculate the sum of the first n terms in the Fibonacci sequence using recursion.

    Parameters:
    n (int): The number of terms in the Fibonacci sequence to sum.

    Returns:
    int: The sum of the first n Fibonacci numbers.

    Raises:
    ValueError: If n is less than 1.
    TypeError: If n is not an integer.
    """
    if not isinstance(n, int):
        raise TypeError("n must be type int")
    if n < 1:
        raise ValueError("n must be positive")

    def fibonacci_recursive(k):
        if k <= 0:
            return 0
        elif k == 1:
            return 1
        else:
            return fibonacci_recursive(k - 1) + fibonacci_recursive(k - 2)

    total_sum = sum(fibonacci_recursive(i) for i in range(1, n + 1))
    return total_sum

def banking_system(transactions):
    """
    Simulates a simple banking system with deposit, withdraw, and check balance operations.

    Parameters:
    transactions (list of tuples): A list where each tuple contains an operation and an amount.

    Returns:
    list of str: A list of transaction history strings.
    """
    balance = 0
    transaction_history = []

    for action, amount in transactions:
        if action == "deposit":
            balance += amount
            transaction_history.append(f"Deposited ${amount}")
        elif action == "withdraw":
            if amount > balance:
                transaction_history.append("Insufficient funds")
            else:
                balance -= amount
                transaction_history.append(f"Withdrew ${amount}")
        elif action == "check_balance":
            transaction_history.append(f"Balance is ${balance}")

    return transaction_history

def product_of_elements(lst):
