    Parameters:
    lst (list): A list of integers.

    Returns:
    int: The product of all elements in the list. Returns 1 if the list is empty.
    """
    if not lst:
        return 1
    else:
        return lst[0] * product_of_elements(lst[1:])

def calculate_exponential(x):
    """
    Calculate 2 raised to the power of x, handling both positive and negative integers.

    Parameters:
    x (int): The exponent to which 2 is raised.

    Returns:
    float: The result of 2^x.
    """
    if x < 0:
        return 1 / (2 ** (-x))
    else:
        result = 1
        for i in range(x):
            result *= 2
        return float(result)

