def apply_operation(func, numbers):
    """
    Applies a given function to each integer in a nested list structure.

    Parameters:
    func (callable): A function that takes a single integer and returns an integer.
    numbers (list): A list of integers and nested lists of integers.

    Returns:
    list: A new list with the results of applying `func` to each integer.
    """
    def _apply_recursively(item):
        if isinstance(item, int):
            return func(item)
        elif isinstance(item, list):
            return [_apply_recursively(subitem) for subitem in item]
        else:
            raise ValueError("The list should contain only integers and nested lists of integers.")

    return _apply_recursively(numbers)

def find_duplicate_integers(numbers):
    """
    Identifies all integers appearing more than once in the input list and returns them sorted in ascending order.

    :param numbers: List of integers
    :return: List of duplicate integers in ascending order
    """
    seen = set()
    duplicates = set()

    for number in numbers:
        if number in seen:
            duplicates.add(number)
        else:
            seen.add(number)

    return sorted(duplicates)

def flatten_json(json_obj: dict, parent_key: str = '', sep: str = '.') -> dict:
    """
    Flattens a nested dictionary into a flat dictionary with keys in the format parent_key.child_key.

    :param json_obj: The dictionary representing the JSON object.
    :param parent_key: The base key string to use for the parent key.
    :param sep: The separator to use between keys.
    :return: A flattened dictionary.
    """
    items = {}
    for k, v in json_obj.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_json(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

def sum_of_primes_below(n):
    """
    Calculate the sum of all prime numbers less than a given number n.

    :param n: An integer representing the upper limit (exclusive).
    :return: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False

    return sum(index for index, prime in enumerate(is_prime) if prime)

def process_input(arg):
