    - If the argument is a string, returns a list with the length of the string.
    - If the argument is None, returns an empty list.
    - For any other type, returns an empty list.
    """
    if isinstance(arg, list):
        return [len(s) for s in arg if isinstance(s, str)]
    elif isinstance(arg, str):
        return [len(arg)]
    elif arg is None:
        return []
    else:
        return []

