    :param data: A dictionary with string keys and integer values.
    :return: A dictionary with integer keys and lists of strings as values.
    """
    inverted_data = {}
    for key, value in data.items():
        if value not in inverted_data:
            inverted_data[value] = [key]
        else:
            inverted_data[value].append(key)
    return inverted_data

def extract_parameters(data, parameter_key, default_value=""):
    """
    Searches for parameter_key in a nested dictionary up to three levels deep.
    Returns a list of values if found and not an empty string, otherwise returns a list with a default value.

    :param data: Nested dictionary to search within.
    :param parameter_key: The key to search for in the dictionary.
    :param default_value: The default value to return if the key is not found or its value is an empty string.
    :return: List of values associated with parameter_key or a list with the default value.
    """
    def search_nested_dict(d, key):
        if key in d and d[key] != "":
            return d[key]
        for value in d.values():
            if isinstance(value, dict):
                result = search_nested_dict(value, key)
                if result is not None:
                    return result
        return None

    for _ in range(3):
        value = search_nested_dict(data, parameter_key)
        if value is not None:
            if isinstance(value, list):
                return value
            else:
                return [value]
        new_data = {}
        for key, val in data.items():
            if isinstance(val, dict):
                new_data.update(val)
        if not new_data:
            break
        data = new_data

    return [default_value]

def generate_prime_numbers(limit):
    """
    Generates a list of prime numbers up to a given limit using the Sieve of Eratosthenes algorithm.

    :param limit: int, the upper bound to generate prime numbers (inclusive)
    :return: list, contains all prime numbers less than or equal to limit
    """
    if limit < 2:
        return []

    is_prime = [True] * (limit + 1)
    is_prime[0], is_prime[1] = False, False

    for number in range(2, int(limit**0.5) + 1):
        if is_prime[number]:
            for multiple in range(number*number, limit + 1, number):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def custom_sort(original_list, custom_order):
    """
    Sorts the original_list based on the custom_order list.
    Integers not in custom_order are appended at the end in their original order.

    :param original_list: List of integers to be sorted.
    :param custom_order: List of integers defining the custom sort order.
    :return: A new list with integers sorted according to custom_order.
    """
    order_index = {item: index for index, item in enumerate(custom_order)}

    def sort_key(item):
        return order_index.get(item, float('inf'))

    return sorted(original_list, key=sort_key)

