def max_profit(prices):
    """
    Calculate the maximum profit from a list of stock prices.

    :param prices: List[int] - A list of integers representing stock prices.
    :return: int - The maximum profit that can be achieved.
    """
    if not prices:
        return 0
    min_price = prices[0]
    max_profit = 0
    for price in prices:
        if price < min_price:
            min_price = price
        else:
            max_profit = max(max_profit, price - min_price)
    return max_profit

