    """
    Returns a list of all prime numbers up to and including n.

    :param n: The upper limit integer up to which primes are to be found.
    :return: A list of prime numbers up to n.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n ** 0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def simplify_path(path: str) -> str:
    """
    Simplifies a given Unix-like file path by removing unnecessary elements such as
    consecutive slashes, dots representing the current directory, and resolving
    references to the parent directory.

    :param path: A string representing the file path.
    :return: A string representing the simplified file path.
    """
    stack = []
    components = path.split('/')
    for component in components:
        if component == '' or component == '.':
            continue
        elif component == '..':
            if stack:
                stack.pop()
        else:
            stack.append(component)
    return '/' + '/'.join(stack)

def fibonacci_recursive(n, memo=None):
    """
    Computes the n-th Fibonacci number using recursion with memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The n-th Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = fibonacci_recursive(n - 1, memo) + fibonacci_recursive(n - 2, memo)
        return memo[n]

def compute_factorial(n):
    """
    Computes the factorial of a given non-negative integer n.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the given integer n.
    """
    if n == 0:
        return 1
    else:
        return n * compute_factorial(n - 1)

def find_common_entities(background_dataset, input_dataset):
