    :param background_dataset: A dictionary where keys are labels and values are lists of entities.
    :param input_dataset: A list of entities.
    :return: A dictionary with labels as keys and sets of common entities as values.
    """
    input_dataset_set = set(input_dataset)
    result = {}

    for label, entities in background_dataset.items():
        common_entities = {entity for entity in entities if entity in input_dataset_set}
        result[label] = common_entities

    return result

