def earliest_transactions(transactions):
    """
    Determine the earliest transaction in each block based on timestamp.
    If timestamps are equal, select the transaction with the lexicographically smallest transaction_id.

    :param transactions: List of dictionaries, each representing a transaction.
    :return: Dictionary with block numbers as keys and tuples (timestamp, transaction_id) as values.
    """
    earliest_tx_by_block = {}

    for tx in transactions:
        block_number = tx['block_number']
        timestamp = tx['timestamp']
        transaction_id = tx['transaction_id']

        if block_number not in earliest_tx_by_block:
            earliest_tx_by_block[block_number] = (timestamp, transaction_id)
        else:
            current_earliest_timestamp, current_earliest_tx_id = earliest_tx_by_block[block_number]

            if timestamp < current_earliest_timestamp:
                earliest_tx_by_block[block_number] = (timestamp, transaction_id)
            elif timestamp == current_earliest_timestamp:
                if transaction_id < current_earliest_tx_id:
                    earliest_tx_by_block[block_number] = (timestamp, transaction_id)

    return earliest_tx_by_block

def match_genes_with_mutations(genes, mutations):
    """
    Matches genes with mutations based on overlapping regions.

    Parameters:
    genes (dict): A dictionary mapping gene regions to gene names.
    mutations (dict): A dictionary mapping mutation regions to mutation types.

    Returns:
    dict: A dictionary mapping gene regions to lists of unique mutation types.
    """
    gene_mutation_map = {gene: [] for gene in genes}

    for mutation, mutation_type in mutations.items():
        for gene in genes:
            if (
                mutation[0] == gene[0] and  # same chromosome
                mutation[1] <= gene[2] and  # mutation start is before or within gene end
                gene[1] <= mutation[2]     # gene start is before or within mutation end
            ):
                if mutation_type not in gene_mutation_map[gene]:
                    gene_mutation_map[gene].append(mutation_type)

    return gene_mutation_map

def determine_stage(ages: list) -> list:
