    """
    def age_to_stage(age: int) -> str:
        if age < 0:
            return "Invalid age"
        elif 0 <= age <= 2:
            return "Infant"
        elif 3 <= age <= 12:
            return "Child"
        elif 13 <= age <= 19:
            return "Teen"
        elif 20 <= age <= 64:
