def find_longest_common_prefix(strs):
    """
    Finds the longest common prefix among a list of strings.

    :param strs: List of strings to find the common prefix for.
    :return: The longest common prefix string or an empty string if no common prefix exists.
    """
    if not strs:
        return ''

    prefix = strs[0]

    for string in strs:
        while string[:len(prefix)] != prefix and prefix:
            prefix = prefix[:-1]

        if not prefix:
            return ''

    return prefix

def iterable_transformer(iterable, fn):
    """
    Recursively applies a function to all elements within a nested iterable structure.

    :param iterable: A nested iterable structure (list, tuple, set, or dict).
    :param fn: A function to apply to each element.
    :return: A new iterable with the same structure, but with all elements transformed.
    """
    if isinstance(iterable, (list, tuple, set)):
        return type(iterable)(iterable_transformer(item, fn) for item in iterable)
    elif isinstance(iterable, dict):
        return {key: iterable_transformer(value, fn) for key, value in iterable.items()}
    else:
        return fn(iterable)

def factorial_memo(n, memo=None):
    """
    Calculate the factorial of a number using memoization.

    :param n: Non-negative integer for which the factorial is to be calculated.
    :param memo: Dictionary to store previously computed factorials.
    :return: Factorial of the number n.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return 1
    else:
        memo[n] = n * factorial_memo(n-1, memo)
        return memo[n]

def parse_itemized_elements(text):
    """
    Parses a string containing itemized elements enclosed in square brackets and returns a dictionary
    with the count of each element.

    :param text: A string with itemized elements separated by commas.
    :return: A dictionary with item names as keys and their counts as values.
    """
    result = {}
    elements = text.split(',')
    for element in elements:
        element = element.strip()
        if element.startswith('[') and element.endswith(']'):
            item = element[1:-1]
            if item in result:
                result[item] += 1
            else:
                result[item] = 1
    return result

def prime_generator(n):
    """
    Generator function to yield prime numbers between 2 and n (inclusive).

    :param n: The upper limit integer (inclusive) to find prime numbers.
    :yield: Prime numbers between 2 and n.
    """
    if n < 2:
        return

    is_prime = [True] * (n + 1)
    p = 2

    while p * p <= n:
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
        p += 1

    for number in range(2, n + 1):
        if is_prime[number]:
            yield number

