    Determines the most common gene name for each protein ID. In cases of ties,
    returns the lexicographically smallest gene name. If no gene names are
    associated with a protein ID, returns an empty string.

    :param memberlist: List of protein IDs (strings).
    :param accession_to_gene: Dictionary mapping gene accessions (strings) to lists of gene names (strings).
    :param prot_id_to_accession: Dictionary mapping protein IDs (strings) to lists of gene accessions (strings).
    :return: Dictionary mapping each protein ID to its best or most common gene name (string).
    """
    def find_most_common_gene(gene_names):
        gene_count = {}
        for name in gene_names:
            gene_count[name] = gene_count.get(name, 0) + 1
        max_count = max(gene_count.values())
        most_common_genes = [name for name, count in gene_count.items() if count == max_count]
        return min(most_common_genes)

    result = {}
    for protein_id in memberlist:
        accessions = prot_id_to_accession.get(protein_id, [])
        gene_names = [name for accession in accessions for name in accession_to_gene.get(accession, [])]
        result[protein_id] = find_most_common_gene(gene_names) if gene_names else ""

    return result

def find_max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell of stocks.

    :param prices: List[int] - A list of integers representing stock prices.
    :return: int - The maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

def clean_latex(input_string):
    """
    Removes extra backslashes from LaTeX code enclosed within dollar signs in the input string.

    Parameters:
    input_string (str): The input string that may contain LaTeX code with extra backslashes.

    Returns:
    str: The cleaned string with extra backslashes removed if it starts and ends with a dollar sign.
    """
    result = ''
    if input_string.startswith('$') and input_string.endswith('$'):
        i = 0
        while i < len(input_string):
            if input_string[i] == '\\':
                i += 1
                if i < len(input_string):
                    result += input_string[i]
            else:
                result += input_string[i]
            i += 1
    else:
        result = input_string
    return result

def shortest_common_supersequence(str1, str2):
    """
    Finds the shortest common supersequence of two strings.

    :param str1: First input string.
    :param str2: Second input string.
    :return: The shortest common supersequence of str1 and str2.
    """
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    i, j = m, n
    s = []
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            s.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            s.append(str1[i - 1])
            i -= 1
        else:
            s.append(str2[j - 1])
            j -= 1

    while i > 0:
        s.append(str1[i - 1])
        i -= 1
    while j > 0:
        s.append(str2[j - 1])
        j -= 1

    s.reverse()
    return ''.join(s)

def quicksort(arr):
    """
    Sorts a list of integers using the quicksort algorithm.

    Parameters:
    arr (list): A list of integers to be sorted.

    Returns:
    list: A sorted list of integers.
    """
    if len(arr) <= 1:
        return arr

    pivot = arr[-1]
    less = []
    equal = []
    greater = []

    for element in arr:
        if element < pivot:
            less.append(element)
        elif element == pivot:
            equal.append(element)
        else:
            greater.append(element)

    return quicksort(less) + equal + quicksort(greater)

def sum_of_squares_of_evens(numbers):
    """
    Computes the sum of the squares of all even numbers in the given list.
    Handles non-numeric elements and empty lists by returning 0.

    :param numbers: List of elements which can be integers, floats, or non-numeric types.
    :return: Integer sum of the squares of the even numbers in the list.
    """
    try:
        return sum(num ** 2 if isinstance(num, (int, float)) and num % 2 == 0 else 0 for num in numbers)
    except TypeError:
        return 0

def convert_to_uppercase_if_no_uppercase_present(s):
    """
    Converts the input string to uppercase if it contains no uppercase letters.
    Otherwise, returns the original string.

    :param s: The input string to be processed.
    :return: The processed string according to the specified rules.
    """
    if any(char.isupper() for char in s):
        return s
    else:
        return s.upper()

def find_max_value(tree):
    """
    Traverses a binary tree represented as a nested dictionary and returns the maximum value found.

    :param tree: A dictionary representing the root of the tree.
    :return: An integer representing the maximum value found in the tree.
    """
    def traverse_and_find_max(node):
        max_value = node['value']
        for child in node['children']:
            max_in_child = traverse_and_find_max(child)
            if max_in_child > max_value:
                max_value = max_in_child
        return max_value

    return traverse_and_find_max(tree)

def find_target_coordinates(maze, target):
    """
    Finds the coordinates of the target integer in the given 2D maze.

    Parameters:
    maze (list of list of int): The 2D grid representing the maze.
    target (int): The target integer to find in the maze.

    Returns:
    tuple or None: A tuple (i, j) representing the coordinates of the target integer,
                   or None if the target is not found.
    """
    for i in range(len(maze)):
        for j in range(len(maze[i])):
            if maze[i][j] == target:
                return (i, j)
    return None

def sort_books_by_pages(books):
    """
    Sorts a list of books in descending order by the number of pages.
    If two books have the same number of pages, they are sorted alphabetically by title.

    :param books: List of dictionaries, each containing 'title', 'author', and 'pages'.
    :return: List of tuples (pages, title) sorted as specified.
    """
    def custom_sort(book):
        return (-book['pages'], book['title'])

    n = len(books)
    for i in range(n):
        for j in range(0, n-i-1):
            if custom_sort(books[j]) > custom_sort(books[j+1]):
                books[j], books[j+1] = books[j+1], books[j]

    return [(book['pages'], book['title']) for book in books]

def best_three_distinct_scores(scores):
    """
    Returns the top three distinct scores in descending order from the given list of scores.

    :param scores: List[int] - A list of integers representing the scores.
    :return: List[int] - A list of the top three distinct scores in descending order.
    """
    def custom_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n-i-1):
                if arr[j] < arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
        return arr

    distinct_scores = []
    for score in scores:
        if score not in distinct_scores:
            distinct_scores.append(score)

    sorted_scores = custom_sort(distinct_scores)

    return sorted_scores[:3]

def generate_stars(value, pattern="default"):
    """
    Generates a string of stars based on the given value and pattern.

    Parameters:
    value (int): The number of stars to generate.
    pattern (str): The pattern of star formation. Can be "solid", "default", "vertical", or "triangle".

    Returns:
    str: A string representing the sequence of stars according to the specified pattern.

    Raises:
    ValueError: If the pattern is not recognized.
    """
    if pattern == "solid" or pattern == "default":
        return " ".join(["*"] * value)
    elif pattern == "vertical":
        return "\n".join(["*"] * value)
    elif pattern == "triangle":
        return "\n".join([" ".join(["*"] * (i + 1)) for i in range(value)])
    else:
        raise ValueError(f"Unknown pattern: {pattern}")

def sum_nested_lists(lst):
    """
    Computes the total sum of all integers in a nested list structure.

    :param lst: A list which may contain integers and/or other lists
    :return: The total sum of all integers in the nested lists
    """
    total_sum = 0
    for element in lst:
        if isinstance(element, list):
            total_sum += sum_nested_lists(element)
        else:
            total_sum += element
    return total_sum

def find_unique_elements(l: list) -> list:
    """
    Flattens a nested list and returns a list of unique elements in the order of their first occurrence.

    :param l: A nested list of integers.
    :return: A list of unique integers from the flattened list.
    """
    def flatten(lst):
        for elem in lst:
            if isinstance(elem, list):
                yield from flatten(elem)
            else:
                yield elem

    seen = set()
    unique_elements = []
    for item in flatten(l):
        if item not in seen:
            unique_elements.append(item)
            seen.add(item)

    return unique_elements

def find_first_even_number(numbers):
    """
    Returns the first even number in the given list of integers.
    If no even number is found, returns None.

    :param numbers: List of integers
    :return: First even integer or None
    """
    for number in numbers:
        if number % 2 == 0:
            return number

def format_title(s):
    """
    Formats a given book title by capitalizing significant words and converting others to lowercase.

    Parameters:
    s (str): The title of the book as a UTF-8 encoded string.

    Returns:
    str: The formatted title of the book.
    """
    small_words = {"a", "an", "the", "and", "but", "or", "for", "nor", "on", "at", "to", "by", "in", "of", "with"}
    words = s.split()
    formatted_words = [
        word[0].upper() + word[1:].lower() if word.lower() not in small_words or i == 0 else word.lower()
        for i, word in enumerate(words)
    ]
    return ' '.join(formatted_words)

def balance_brackets(brackets: str) -> bool:
    """
    Determines if the brackets in the given string are balanced.

    :param brackets: A string containing various characters, including brackets.
    :return: True if the brackets are balanced, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', ']': '[', '}': '{'}

    for char in brackets:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return not stack

def deep_copy_structure(obj):
    """
    Recursively creates a deep copy of a nested dictionary or list.

    Parameters:
    obj (list or dict): The nested structure to be copied.

    Returns:
    list or dict: A deep copy of the input structure.
    """
    if isinstance(obj, list):
        return [deep_copy_structure(item) for item in obj]
    elif isinstance(obj, dict):
        return {key: deep_copy_structure(value) for key, value in obj.items()}
    else:
        return obj

def find_nth_fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The nth Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return find_nth_fibonacci(n - 1) + find_nth_fibonacci(n - 2)

def integer_frequencies(input_list):
    """
    Computes the frequency of each integer in the input list and returns a dictionary
    with integers as keys and their frequencies as values.

    :param input_list: List of integers
    :return: Dictionary with integers as keys and their frequencies as values
    """
    frequency_dict = {}
    for num in input_list:
        if num in frequency_dict:
            frequency_dict[num] += 1
        else:
            frequency_dict[num] = 1
    return frequency_dict

def subsample_hessian(H, mask):
    """
    Returns the submatrix of the Hessian corresponding to the elements of the parameters
    indicated by the binary masks. If mask is None, returns the original Hessian matrix.

    :param H: List of lists representing the Hessian matrix.
    :param mask: Dictionary with keys as row indices and values as binary lists.
    :return: List of lists representing the submatrix of the Hessian.
    """
    if mask is None:
        return H

    sub_H = []

    for i in range(len(H)):
        if i in mask:
            row_mask = mask[i]
            new_row = []
            for j in range(len(H[i])):
                if j < len(row_mask) and row_mask[j] & 1:
                    new_row.append(H[i][j])
            if new_row:
                sub_H.append(new_row)

    return sub_H

def frequency_of_elements(input_list):
    """
    Returns a list containing the frequency of each unique element in the input list.
    The order of the frequencies corresponds to the first occurrence of each unique element.

    :param input_list: List of integers
    :return: List of integers representing the frequency of each unique element
    """
    frequency = {}
    for element in input_list:
        if element in frequency:
            frequency[element] += 1
        else:
            frequency[element] = 1
    return [frequency[element] for element in dict.fromkeys(input_list)]

def check_integrity(original_dict, received_dict):
    """
    Checks if two dictionaries are structurally identical, including handling deep nesting and circular references.

    :param original_dict: The original dictionary to compare.
    :param received_dict: The received dictionary to compare against the original.
    :return: True if the dictionaries are identical, False otherwise.
    """
    def compare_dicts(o_dict, r_dict, seen):
        if id(o_dict) == id(r_dict):
            return True

        if not isinstance(o_dict, dict) or not isinstance(r_dict, dict):
            return False

        if id(o_dict) in seen or id(r_dict) in seen:
            return True

        seen.add(id(o_dict))
        seen.add(id(r_dict))

        if o_dict.keys() != r_dict.keys():
            return False

        for key in o_dict:
            if isinstance(o_dict[key], dict):
                if not compare_dicts(o_dict[key], r_dict[key], seen):
                    return False
            else:
                if o_dict[key] != r_dict[key]:
                    return False

        return True

    return compare_dicts(original_dict, received_dict, set())

def compare_objects(prev_obj, new_obj, fields=[]):
    """
    Compares the specified fields of two objects for equality.

    :param prev_obj: The first object to compare.
    :param new_obj: The second object to compare.
    :param fields: A list of field names to compare. If empty, compares all non-private fields.
    :return: True if the specified fields are equal in both objects, False otherwise.
    """
    def get_field_names(obj):
        return [name for name in dir(obj) if not name.startswith('_')]

    def get_value(obj, field_name):
        return obj.__getattribute__(field_name)

    if not fields:
        fields = get_field_names(prev_obj)
        fields = [field for field in fields if field in get_field_names(new_obj)]

    for field in fields:
        try:
            prev_value = get_value(prev_obj, field)
            new_value = get_value(new_obj, field)
            if prev_value != new_value:
                return False
        except AttributeError:
            return False

    return True

def is_palindrome_substring(s, queries):
    """
    Determines if each substring specified by the queries is a palindrome.

    :param s: The input string.
    :param queries: A list of tuples, where each tuple (start, end) represents a substring.
    :return: A list of boolean values indicating whether each substring is a palindrome.
    """
    n = len(s)
    is_palindrome = [[False] * n for _ in range(n)]

    for i in range(n):
        is_palindrome[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            is_palindrome[i][i + 1] = True

    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    results = []
    for start, end in queries:
        if start < 0 or end >= n or start > end:
            results.append(False)
        else:
            results.append(is_palindrome[start][end])

    return results

def count_frequencies(s):
    """
    Counts the frequency of each character in the given string.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their frequencies as values.
    """
    frequencies = {}
    for char in s:
        if char in frequencies:
            frequencies[char] += 1
        else:
            frequencies[char] = 1
    return frequencies

def validate_lines(lines, matches):
    """
    Validates if each line in lines is a full match with its corresponding full match in matches.

    Parameters:
    lines (list of str): The list of strings to validate.
    matches (dict): A dictionary where keys are partial matches and values are full matches.

    Returns:
    bool: True if all lines are full matches, False otherwise.
    """
    for line in lines:
        for partial, full in matches.items():
            if line.startswith(partial):
                if any(char.isdigit() for char in line[len(partial):]):
                    return False
                if line != full:
                    return False
    return True

import math

def closest_to_origin(points):
    """
    Returns the point closest to the origin (0, 0, 0) from a list of 3D points.

    Parameters:
    points (list of tuples): A list where each tuple contains three integers representing a point in 3D space.

    Returns:
    tuple or None: The point closest to the origin, or None if the list is empty.
    """
    if not points:
        return None

    def euclidean_distance(point):
        return math.sqrt(point[0]**2 + point[1]**2 + point[2]**2)

    return min(points, key=euclidean_distance)

def text_categorizer(text):
    """
    Recursively categorizes characters in the input string into Uppercase letters,
    Lowercase letters, Punctuation marks, Digits, and Whitespace characters.

    Parameters:
    text (str): The input string to be categorized.

    Returns:
    dict: A dictionary with categories as keys and counts of characters as values.
    """
    def helper(text, counts):
        if not text:
            return counts
        char = text[0]
        if char.isupper():
            counts['Uppercase letters'] += 1
        elif char.islower():
            counts['Lowercase letters'] += 1
        elif char.isdigit():
            counts['Digits'] += 1
        elif char.isspace():
            counts['Whitespace characters'] += 1
        else:
            counts['Punctuation marks'] += 1
        return helper(text[1:], counts)

    initial_counts = {
        'Uppercase letters': 0,
        'Lowercase letters': 0,
        'Punctuation marks': 0,
        'Digits': 0,
        'Whitespace characters': 0
    }

    return helper(text, initial_counts)

def escape_special_characters(input_string):
    """
    Escapes special characters in the input string according to specified rules.

    Parameters:
    input_string (str): The string to be processed.

    Returns:
    str: The processed string with special characters escaped.
    """
    if input_string == "":
        return "NULL"

    escaped_string = []
    i = 0
    while i < len(input_string):
        char = input_string[i]
        if char == '\\':
            if i + 1 < len(input_string) and input_string[i + 1] in ('\\', 'n', "'"):
                escaped_string.append(char + input_string[i + 1])
                i += 2
            else:
                escaped_string.append('\\\\')
                i += 1
        elif char == '\n':
            escaped_string.append('\\n')
            i += 1
        elif char == "'":
            escaped_string.append("''")
            i += 1
        else:
            escaped_string.append(char)
            i += 1

    return ''.join(escaped_string)

def longest_valid_parentheses(s: str) -> int:
    """
    Finds the length of the longest valid parentheses substring in the given string s.

    :param s: A string consisting of '(' and ')' characters.
    :return: The length of the longest valid parentheses substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with base value -1

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

def average_of_two(x, y):
    """
    Computes the average of corresponding elements from two lists x and y.
    If one element is None, the non-None element is used.
    If both elements are None, the result is None.

    :param x: List of integers, floats, or None
    :param y: List of integers, floats, or None
    :return: List of computed averages or None values
    """
    def element_average(a, b):
        if a is not None and b is not None:
            return (a + b) / 2
        elif a is not None:
            return a
        elif b is not None:
            return b
        else:
            return None

    return [element_average(xi, yi) for xi, yi in zip(x, y)]

def generate_prime_factors(n):
    """
    Returns a list of prime factors of the given integer n in non-decreasing order.
    If n is less than 2, returns an empty list.

    :param n: Integer to factorize
    :return: List of prime factors
    """
    def prime_factors(n):
        factors = []
        # Check for smallest prime number 2
        while n % 2 == 0:
            factors.append(2)
            n //= 2
        # Check for odd prime numbers from 3 onwards
        for i in range(3, int(n**0.5) + 1, 2):
            while n % i == 0:
                factors.append(i)
                n //= i
        # If n is still greater than 2, then it is a prime number
        if n > 2:
            factors.append(n)
        return factors

    if n < 2:
        return []
    else:
        return prime_factors(n)

def snake_case_to_camel_case(snake_case_str):
    """
    Convert a snake_case string to CamelCase in a single pass.

    :param snake_case_str: A string in snake_case format.
    :return: A string in CamelCase format.
    """
    camel_case_str = ''
    capitalize_next = False

    for char in snake_case_str:
        if char == '_':
            capitalize_next = True
        else:
            if capitalize_next:
                camel_case_str += char.upper()
                capitalize_next = False
            else:
                camel_case_str += char

    return camel_case_str

def filter_special_characters(input_string, special_characters): 
    """Return a new string with all occurrences of the special characters removed from the input_string."""
    return ''.join(char for char in input_string if char not in special_characters)

def greatest_height_difference(buildings):
    """
    Returns the indices of the two buildings with the greatest height difference.

    :param buildings: List of integers representing the heights of buildings.
    :return: Tuple of two indices with the greatest height difference.
    """
    if len(buildings) < 2:
        raise ValueError("At least two buildings are required")

    max_height = buildings[0]
    min_height = buildings[0]
    max_index = 0
    min_index = 0

    for i in range(1, len(buildings)):
        if buildings[i] > max_height:
            max_height = buildings[i]
            max_index = i
        if buildings[i] < min_height:
            min_height = buildings[i]
            min_index = i

    return (min_index, max_index)

def find_smallest_prime_divisor(n):
    """
    Returns the smallest prime divisor of a given positive integer n.
    If n is a prime number, returns n itself.
    Returns None if n is 1.
    """
    if n <= 1:
        return None
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

def merge_data(data1, data2):
    """
    Merges two data structures according to specific rules:
    - Dictionaries are merged recursively and sorted by keys.
    - Lists are merged, duplicates are removed, and sorted numerically or lexicographically.
    - A dictionary and a list result in the sorted dictionary.
    - None is ignored, and the other input is returned.
    - Strings are compared by length and lexicographical order.
    - A string and a non-string result in the non-string.
    """
    def merge_dicts(d1, d2):
        """
        Recursively merges two dictionaries and sorts by keys.
        """
        for key in sorted(set(d1) | set(d2)):
            if key in d1 and key in d2:
                if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    yield key, dict(merge_dicts(d1[key], d2[key]))
                else:
                    yield key, d2[key]
            elif key in d1:
                yield key, d1[key]
            else:
                yield key, d2[key]

    def sort_list(lst):
        """
        Sorts a list numerically or lexicographically, placing numbers before strings.
        """
        numbers = sorted([x for x in lst if isinstance(x, (int, float))])
        strings = sorted([x for x in lst if isinstance(x, str)])
        return numbers + strings

    if data1 is None:
        return data2
    if data2 is None:
        return data1
    if isinstance(data1, str) and isinstance(data2, str):
        if len(data1) == len(data2):
            return min(data1, data2)
        return max(data1, data2, key=len)
    if isinstance(data1, str):
        return data2
    if isinstance(data2, str):
        return data1
    if isinstance(data1, dict) and isinstance(data2, dict):
        return dict(merge_dicts(data1, data2))
    if isinstance(data1, list) and isinstance(data2, list):
        return sort_list(set(data1) | set(data2))
    if isinstance(data1, dict):
        return {k: data1[k] for k in sorted(data1)}
    if isinstance(data2, dict):
        return {k: data2[k] for k in sorted(data2)}
    return None

def count_primes(n):
    """
    Returns the number of prime numbers less than or equal to n using the Sieve of Eratosthenes algorithm.

    :param n: A positive integer
    :return: The count of prime numbers less than or equal to n
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    is_prime[0], is_prime[1] = False, False

    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    return sum(is_prime)

def count_distinct_substrings(s):
    """
    Counts the number of distinct substrings in a given string s.

    :param s: A string consisting of lowercase English letters.
    :return: An integer representing the number of distinct substrings.
    """
    seen = set()
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            seen.add(s[i:j])
    return len(seen)

def find_most_common_element(lst):
    """
    Returns the most common element in the list. If there are multiple elements
    with the same maximum frequency, returns the smallest one.

    :param lst: List of integers
    :return: Integer, the most common element
    """
    # Initialize a dictionary to store the frequency of each element
    frequency = {}

    # Count the occurrences of each element in the list
    for num in lst:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Find the element with the maximum frequency
    max_freq = 0
    most_common_element = None

    for num, freq in frequency.items():
        if freq > max_freq:
            max_freq = freq
            most_common_element = num
        elif freq == max_freq:
            if most_common_element is None or num < most_common_element:
                most_common_element = num

    return most_common_element

import typing

def is_special_type(a_type: typing.Any) -> bool:
    """
    Determines if the provided Python type is a nested typing.Union
    that contains at least one non-nested type which is a subclass of str.

    :param a_type: The Python type to check.
    :return: True if the type is a nested typing.Union with at least one non-nested type being a subclass of str, False otherwise.
    """
    if hasattr(a_type, '__origin__') and a_type.__origin__ is typing.Union:
        for arg in a_type.__args__:
            if isinstance(arg, type) and issubclass(arg, str):
                return True
            elif hasattr(arg, '__origin__') and arg.__origin__ is typing.Union:
                if is_special_type(arg):
                    return True
    return False

def fast_exponentiation(base, exponent):
    """
    Computes base raised to the power of exponent using an efficient recursive method.

    Parameters:
    base (float): The base number.
    exponent (int): The exponent, which can be positive, negative, or zero.

    Returns:
    float: The result of base raised to the power of exponent.
    """
    if exponent < 0:
        return 1 / fast_exponentiation(base, -exponent)

    if exponent == 0:
        return 1
    elif exponent % 2 == 0:
        half_power = fast_exponentiation(base, exponent // 2)
        return half_power * half_power
    else:
        return base * fast_exponentiation(base, exponent - 1)

def indent_string_list(strings: list, spaces: int = 2) -> list:
