    In case of a tie, returns the smallest integer among them.
    Returns None if the list is empty.

    :param numbers: List of integers
    :return: Integer with the highest frequency or None if the list is empty
    """
    if not numbers:
        return None

    frequency = {}

    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    max_occurrence = max(frequency.values())

    result = min(number for number, count in frequency.items() if count == max_occurrence)

