def max_consecutive_occurrences(s, chars):
    """
    Returns a dictionary with each character from the list `chars` as a key
    and the maximum number of consecutive occurrences of that character in the
    string `s` as the value.

    :param s: A string consisting of lowercase English letters.
    :param chars: A list of distinct lowercase English letters.
    :return: A dictionary with maximum consecutive occurrences for each character.
    """
    result = {char: 0 for char in chars}
    current_char_count = {char: 0 for char in chars}

    for i, char in enumerate(s):
        if char in current_char_count:
            if i > 0 and char == s[i - 1]:
                current_char_count[char] += 1
            else:
                current_char_count[char] = 1
            result[char] = max(result[char], current_char_count[char])

    return result

