def factorize_number(n):
    """
    Returns a dictionary with prime factors as keys and their respective exponents as values.

    :param n: Integer to be factorized
    :return: Dictionary of prime factors and their exponents
    """
    def prime_factors(n):
        i = 2
        factors = {}
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors[i] = factors.get(i, 0) + 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    return prime_factors(n)

