def find_nth_root(n, k):
    """
    Computes the integer part of the k-th root of a positive integer n using binary search.

    Parameters:
    n (int): The number to find the k-th root of.
    k (int): The degree of the root.

    Returns:
    int: The integer part of the k-th root of n.
    """
    if n == 0 or n == 1:
        return n

    low, high = 1, n
    precision = 1e-7

    for _ in range(50):
        mid = (low + high) / 2
        mid_power_k = mid ** k

        if abs(mid_power_k - n) < precision:
            return round(mid)
        elif mid_power_k < n:
            low = mid
        else:
            high = mid

    return round((low + high) / 2)

def is_magic_matrix(matrix):
    """
    Determines if a given n x n matrix is a Magic Matrix.

    A Magic Matrix is defined as a square matrix where the sum of the elements
    in each row, each column, and both diagonals are equal.

    :param matrix: List[List[int]] - A 2D list of integers representing the matrix.
    :return: bool - True if the matrix is a Magic Matrix, False otherwise.
    """
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        return False

    magic_sum = sum(matrix[0])

    for i in range(n):
        if sum(matrix[i]) != magic_sum:
            return False

    for j in range(n):
        column_sum = 0
        for i in range(n):
            column_sum += matrix[i][j]
        if column_sum != magic_sum:
            return False

    main_diagonal_sum = sum(matrix[i][i] for i in range(n))
    if main_diagonal_sum != magic_sum:
        return False

    secondary_diagonal_sum = sum(matrix[i][n - i - 1] for i in range(n))
    if secondary_diagonal_sum != magic_sum:
        return False

    return True

def validate_identifiers(identifiers):
    """
    Validates a list of medical reference identifiers.

    Parameters:
    identifiers (list of str): A list of strings representing identifiers.

    Returns:
    list of bool: A list of boolean values indicating the validity of each identifier.
    """
    valid_prefixes = {"OMIM", "ORPH", "DECI", "DISEASE", "PMID"}
    seen_numbers = set()
    results = []

    for identifier in identifiers:
        parts = identifier.split(':')

        if len(parts) != 2:
            results.append(False)
            continue

        prefix, number = parts

        if prefix in valid_prefixes and number.isdigit() and number:
            if number not in seen_numbers:
                seen_numbers.add(number)
                results.append(True)
            else:
                results.append(False)
        else:
            results.append(False)

    return results

def is_valid_brackets(sequence):
    """
    Determines if the sequence of brackets is valid.

    Args:
    sequence (str): A string consisting of '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the sequence is valid, False otherwise.
    """
    stack = []
    bracket_map = {")": "(", "}": "{", "]": "["}

    for char in sequence:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False
        else:
            return False

    return not stack

