from collections import deque

def is_bipartite(graph):
    """
    Determines if a given graph is bipartite using an adjacency matrix representation.

    :param graph: List[List[int]], an adjacency matrix representing the graph.
    :return: bool, True if the graph is bipartite, False otherwise.
    """
    num_vertices = len(graph)
    color = [-1] * num_vertices

    for start in range(num_vertices):
        if color[start] == -1:
            color[start] = 0
            queue = deque([start])

            while queue:
                vertex = queue.popleft()
                current_color = color[vertex]

                for neighbor, edge_exists in enumerate(graph[vertex]):
                    if edge_exists:
                        if color[neighbor] == -1:
                            color[neighbor] = 1 - current_color
                            queue.append(neighbor)
                        elif color[neighbor] == current_color:
                            return False
    return True

import re

def parse_html_tags(html_content):
    """
    Parses the given HTML content and returns a dictionary with the count of each opening tag.

    :param html_content: A string representing the HTML content.
    :return: A dictionary with tag names as keys and their counts as values.
    """
    tag_pattern = re.compile(r'<(/?)(\w+)')
    tags = tag_pattern.findall(html_content)
    tag_counts = {}

    for is_closing, tag in tags:
        if not is_closing:
            if tag in tag_counts:
                tag_counts[tag] += 1
            else:
                tag_counts[tag] = 1

    return tag_counts

def fibonacci_recursive(n):
    """
    Computes the nth Fibonacci number using a recursive approach.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The nth Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

