    Parameters:
    angle (float): The angle in degrees to be transformed, ranging from 0 to 360.

    Returns:
    float: The transformed angle in degrees, ranging from 0 to 180, with precision up to six decimal places.
    """
    if not (0 <= angle <= 360):
