def encode_message(message):
    """
    Encodes a given string using a Caesar cipher with a shift of 3.
    Only alphabetic characters are encoded, while other characters remain unchanged.

    :param message: The input string to be encoded.
    :return: The encoded string.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 3) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 3) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in message)

