def transform_json_keys(json_obj, mapping, visited=None):
    """
    Transforms the keys of a JSON object according to a provided mapping.
    Handles nested JSON objects and arrays, and avoids infinite loops due to circular references.

    :param json_obj: The JSON object to transform (can be a dictionary or list).
    :param mapping: A dictionary mapping original keys to new keys.
    :param visited: A set of visited object ids to handle circular references.
    :return: A new JSON object with transformed keys.
    """
    if visited is None:
        visited = set()

    obj_id = id(json_obj)
    if obj_id in visited:
        return None

    visited.add(obj_id)

    if isinstance(json_obj, dict):
        new_dict = {}
        for key, value in json_obj.items():
            if key in mapping:
                new_key = mapping[key]
                new_value = transform_json_keys(value, mapping, visited)
                if new_value is not None:
                    new_dict[new_key] = new_value
        visited.remove(obj_id)
        return new_dict

    elif isinstance(json_obj, list):
        new_list = []
        for item in json_obj:
            new_item = transform_json_keys(item, mapping, visited)
            if new_item is not None:
                new_list.append(new_item)
        visited.remove(obj_id)
        return new_list

    visited.remove(obj_id)
    return json_obj

