def max_non_decreasing_subsequence(nums):
    """
    Calculate the length of the longest non-decreasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest non-decreasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize the dp array with 1s, as the minimum length of subsequence is 1 (number itself)

    for i in range(1, n):
        for j in range(i):
            if nums[i] >= nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def convert_to_nested_dict(keys, value):
    """
    Constructs a nested dictionary from a list of keys and a value.

    Parameters:
    keys (list of str): A list of keys determining the levels of nesting.
    value (int): The value to be placed at the innermost level of the nested dictionary.

    Returns:
    dict: A nested dictionary with the specified keys and value.
    """
    if not keys:
        return {}
    inner_dict = value
    for key in reversed(keys):
        inner_dict = {key: inner_dict}
    return inner_dict

