def longest_palindromic_substring(s: str) -> str:
    """
    Finds the longest palindromic substring in the given string using dynamic programming.

    :param s: Input string
    :return: Longest palindromic substring
    """
    n = len(s)
    if n == 0:
        return ""

    dp = [[False] * n for _ in range(n)]
    start, max_length = 0, 1

    for i in range(n):
        dp[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1
            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True
                if k > max_length:
                    start = i
                    max_length = k

    return s[start:start + max_length]

def factorial(n: int) -> int:
    """
    Computes the factorial of a given integer n using recursion.

    Parameters:
    n (int): The integer for which the factorial is to be computed.

    Returns:
    int: The factorial of n if n is non-negative, otherwise -1.
    """
    if n < 0:
        return -1
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def countDigits(sentence):
    """
    Counts the number of digits in the given sentence without using loops or built-in counting functions.

    :param sentence: A string containing words, punctuation, and digits.
    :return: The total number of digits in the sentence.
    """
    def is_digit(ch):
        return '0' <= ch <= '9'

    def count_recursive(index, count):
        if index == len(sentence):
            return count
        else:
            return count_recursive(index + 1, count + (1 if is_digit(sentence[index]) else 0))

    return count_recursive(0, 0)

def find_prime_factors(n):
    """
    Returns a list of tuples representing the prime factors of n and their multiplicities.

    :param n: Integer, the number to factorize.
    :return: List of tuples (prime, multiplicity).
    """
    factors = {}
    # Check for number of 2s in n
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2

    # Check for odd factors from 3 onwards
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        factors[n] = 1

    return sorted(factors.items())

def is_task_in_queue(queue, task):
    """
    Check if a given task is present in the queue based on task_id and task_no.

    :param queue: List of tuples, where each tuple is of the form (task_id, task_no).
    :param task: Tuple of the form (task_id, task_no) representing the task to be checked.
    :return: True if the task is found in the queue, False otherwise.
    """
    task_id, task_no = task
    for q_task_id, q_task_no in queue:
        if q_task_id == task_id:
            if isinstance(q_task_no, list):
                return task_no in q_task_no
            else:
                return q_task_no == task_no
    return False

def longest_increasing_subsequence(nums):
    """
    Finds the length of the longest increasing subsequence in a list of integers.

    :param nums: List of integers.
    :return: Length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def find_max_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values from the list.

    :param numbers: List of integers
    :return: Tuple (max_value, min_value)
    :raises ValueError: If the list is empty
    """
    if not numbers:
        raise ValueError("The list is empty")

    max_val = min_val = numbers[0]

    for number in numbers[1:]:
        if number > max_val:
            max_val = number
        elif number < min_val:
            min_val = number

    return (max_val, min_val)

def fibonacci(n):
    """
    Computes the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The nth Fibonacci number.

    Raises:
    TypeError: If the input is not an integer.
    ValueError: If the input is a negative integer.
    """
    if not isinstance(n, int):
        raise TypeError("The input must be a non-negative integer")
    if n < 0:
        raise ValueError("The input must be a non-negative integer")
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def sum_of_squares(numbers):
    """
    Computes the sum of squares of a list of integers.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    int or str: The sum of squares of the integers if input is valid, 
                otherwise an error message.
    """
    try:
        if not isinstance(numbers, list):
            raise ValueError("Input should be a list.")
        if not all(isinstance(x, int) for x in numbers):
            raise ValueError("All elements in the list should be integers.")

        return sum(x**2 for x in numbers)

    except ValueError as e:
        return str(e)

def search_binary(array, target):
    """
    Perform a binary search on a sorted array to find the index of the target element.

    Parameters:
    array (list of int): The sorted array to search.
    target (int): The target element to find.

    Returns:
    int: The index of the target element if found, otherwise -1.
    """
    def recursive_search(low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if array[mid] == target:
            return mid
        elif array[mid] > target:
            return recursive_search(low, mid - 1)
        else:
            return recursive_search(mid + 1, high)

    return recursive_search(0, len(array) - 1)

def classify_numbers(numbers):
    """
    Classifies a list of integers into positive and negative numbers.

    Parameters:
    numbers (list of int): The list of integers to classify.

    Returns:
    dict: A dictionary with keys 'positive' and 'negative', each mapping to a list of integers.
    """
    result = {"positive": [], "negative": []}
    for number in numbers:
        if number > 0:
            result["positive"].append(number)
        elif number < 0:
            result["negative"].append(number)
    return result

def palindrome_checker(s: str) -> bool:
    """
    Determines if the given string is a palindrome, ignoring non-alphanumeric characters and case differences.

    :param s: The input string to check.
    :return: True if the string is a palindrome, False otherwise.
    :raises TypeError: If the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    cleaned = []
    for char in s:
        if ('a' <= char <= 'z') or ('A' <= char <= 'Z') or ('0' <= char <= '9'):
            cleaned.append(char.lower())

    left, right = 0, len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1

    return True

def validate_data(data):
    """
    Validates if the input data and all its constituents are not None.

    Args:
    data: A data structure which can be of any type, including nested structures.

    Returns:
    bool: True if data and all its constituents are not None, False otherwise.
    """
    if data is None:
        return False
    elif isinstance(data, dict):
        return all(validate_data(v) for v in data.values())
    elif isinstance(data, (list, tuple, set)):
        return all(validate_data(v) for v in data)
    else:
        return True

def fibonacci_sequence(n, memo=None):
    """
    Generate the first n numbers of the Fibonacci sequence using recursion with memoization.

    :param n: The number of Fibonacci numbers to generate.
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: A list containing the first n Fibonacci numbers.
    """
    if memo is None:
        memo = {}

    def fib_recursive(k):
        if k in memo:
            return memo[k]
        if k <= 1:
            return k
        memo[k] = fib_recursive(k - 1) + fib_recursive(k - 2)
        return memo[k]

    return [fib_recursive(i) for i in range(n)]

def factorial(n):
    """
    Computes the factorial of a non-negative integer using recursion.

    Parameters:
    n (int): The number for which the factorial is to be computed.

    Returns:
    int or str: The factorial of the number if valid, otherwise an error message.
    """
    # Check for invalid inputs
    if not isinstance(n, int):
        return "Error: Input must be an integer."
    if n < 0:
        return "Error: Factorial is not defined for negative numbers."
    # Base case of recursion
    if n == 0 or n == 1:
        return 1
    # Recursive case
    else:
        return n * factorial(n - 1)

from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion with memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The nth Fibonacci number.

    Raises:
    ValueError: If n is a negative integer.
    """
    if n < 0:
        raise ValueError("Fibonacci number is not defined for negative indices")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def get_value_from_file(file_contents: str, key: str) -> float or None:
    """
    Parses the given file contents to find the value associated with the specified key.
    Returns the value as a float if the key is found, otherwise returns None.

    :param file_contents: A string representing the contents of a text file with key-value pairs.
    :param key: A string representing the key to search for in the file contents.
    :return: The corresponding floating-point value if the key is found, otherwise None.
    """
    for line in file_contents.splitlines():
        line = line.strip()
        if not line or '=' not in line:
            continue
        line_key, line_value = line.split('=', 1)
        line_key = line_key.strip()
        line_value = line_value.strip()
        if line_key == key:
            try:
                return float(line_value)
            except ValueError:
                return None
    return None
